// The row-level roll-up: a ledger carrying one synthesized attempt taints the whole
// activity, and Classified is true for an activity the classifier could type.
func TestConstructionRowsToContract_CarriesLedgerAndWorstOrigin(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"C-BE": {ActivityID: "C-BE", Attempts: []projectstate.TaskAttempt{
			{AttemptID: "C-BE:codeReview:1", Task: projectstate.TaskCodeReview, Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginObserved}},
			{AttemptID: "C-BE:construction:1", Task: projectstate.TaskConstruction, Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginSynthesized}},
		}},
	}
	meta := map[string]projectstate.ActivityItem{"C-BE": {Name: "C-BE", WorkerClass: "junior-developer", Coding: true}}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})["C-BE"]
	if len(got.Attempts) != 2 {
		t.Fatalf("Attempts len = %d, want 2", len(got.Attempts))
	}
	if !got.Classified {
		t.Errorf("Classified = false, want true for a typed activity")
	}
	if got.WorstOrigin == nil || *got.WorstOrigin != string(projectstate.OriginSynthesized) {
		t.Errorf("WorstOrigin = %v, want %q — one synthesized attempt taints the row", got.WorstOrigin, projectstate.OriginSynthesized)
	}
	if !got.Recorded {
		t.Errorf("Recorded = false on a row backed by stored head-state")
	}
}

// An activity the classifier refuses to type must assert NOTHING: ClassifyType's
// failure return is ActivityTypeService (also the enum zero), so a passthrough
// rendered ~60 committed rows as Service builds with a full Service lifecycle.
// Classified is the tag of the discriminated union; the visible half of the rule is
// that the row carries ZERO lifecycle sub-rows — and, per task 11 item 3, no coarse
// BuildStatus/Phase chip either: a row with no sub-rows to justify it must not assert
// "Integrated" beside "Unclassified".
func TestConstructionRowsToContract_UnclassifiableAssertsNoLifecycle(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		// No activity-list metadata (workerClass "", coding false) and no service
		// contract — exactly the slot-9 id mismatch that leaves 60 of 69 rows untyped.
		// Every phase is complete, so a classified row would derive Phase=Done and
		// BuildStatus=Integrated — proving the zero values below come from the
		// Classified gate, not merely from an input that happens to derive zero.
		"C-AA": {ActivityID: "C-AA", Attempts: allServiceLedger()},
	}
	got := constructionRowsToContract(rows, map[string]projectstate.ActivityItem{}, nil, constructionPlan{})["C-AA"]
	if got.Classified {
		t.Errorf("Classified = true, want false — the classifier has no rule for this row")
	}
	if len(got.Phases) != 0 {
		t.Errorf("Phases = %+v, want none — an unclassifiable row renders no lifecycle sub-rows", got.Phases)
	}
	if got.Variant != 0 {
		t.Errorf("Variant = %d, want 0 — an untyped row cannot be a testing variant", got.Variant)
	}
	// Type/Kind are undefined while Classified is false and must not be read; they are
	// pinned to the zero value only so nothing downstream sees a stale classification.
	if got.Type != 0 || got.Kind != 0 {
		t.Errorf("Type/Kind = %d/%d, want the zero value on an unclassified row", got.Type, got.Kind)
	}
	// Phase/BuildStatus are likewise undefined while Classified is false, even though
	// every phase above is complete and would derive Done/Integrated if this row were
	// classified — the UI must never show a build-status chip with no sub-rows behind it.
	if got.Phase != 0 {
		t.Errorf("Phase = %d, want the zero value — an unclassified row must not assert a lifecycle phase", got.Phase)
	}
	if got.BuildStatus != 0 {
		t.Errorf("BuildStatus = %d, want the zero value — an unclassified row must not assert a build status", got.BuildStatus)
	}
}

// App A's binary exit criterion: a phase is complete iff its GATE task's latest
// attempt passed. A stored flag nobody can trace to a review does not survive a
// ledger that contradicts it.
func TestPhasesToContract_DerivesCompletedFromTheLedger(t *testing.T) {
	attempts := []projectstate.TaskAttempt{
		// The design gate PASSED and was then REJECTED: the latest attempt decides.
		{AttemptID: "C-x:designReview:1", Task: projectstate.TaskDesignReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
		{AttemptID: "C-x:designReview:2", Task: projectstate.TaskDesignReview, Attempt: 2, Outcome: projectstate.OutcomeRejected},
		// The construction gate PASSED though storage says not done.
		{AttemptID: "C-x:codeReview:1", Task: projectstate.TaskCodeReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
	}
	// The Service profile's row set is the canonical five: requirements(0),
	// detailedDesign(1), testPlan(2), construction(3), integration(4).
	got := phasesToContract(resolvedPhaseCompletions(projectstate.ProfileFor(projectstate.ActivityTypeService, 0), attempts))
	if len(got) != 5 {
		t.Fatalf("phasesToContract len = %d, want 5", len(got))
	}
	if got[1].Completed {
		t.Errorf("detailedDesign Completed = true, want false — its latest designReview was rejected")
	}
	if !got[3].Completed {
		t.Errorf("construction Completed = false, want true — its codeReview passed")
	}
}

// A row with NO ledger asserts nothing: there is no second record for the ledger's
// silence to contradict any more (stage-3 task 4), so the honest answer is an empty
// resolution rather than a materialized skeleton of unknowns.
func TestPhasesToContract_AnEmptyLedgerAssertsNothing(t *testing.T) {
	got := phasesToContract(resolvedPhaseCompletions(projectstate.ProfileFor(projectstate.ActivityTypeService, 0), nil))
	if len(got) != 0 {
		t.Fatalf("phasesToContract len = %d, want 0 — a row with no ledger claims nothing", len(got))
	}
}

// Regression guard for the compute-at-read wiring itself (CoarsePhaseFor /
// CoarseBuildStatusFor inside constructionRowsToContract). Every other test for the
// rule calls the projectstate helpers directly; this one goes through the mapper the
// GetProject read path actually uses, with STORED values that disagree with the
// phase set. A revert to the stored passthrough fails here.
func TestConstructionRowsToContract_DerivesPhaseAndBuildStatusNotStored(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		// Stored says NotStarted / InConstruction; every profile phase is complete.
		"C-BE": {
			ActivityID: "C-BE",
			Attempts:   allServiceLedger(),
		},
		// Stored says Done / Integrated; the phase set says the work has not started.
		"C-FE": {
			ActivityID:  "C-FE",
			CompletedAt: &testExitAt,
			Attempts:    openLedger(),
		},
	}
	meta := map[string]projectstate.ActivityItem{
		"C-BE": {Name: "C-BE", WorkerClass: "junior-developer", Coding: true},
		"C-FE": {Name: "C-FE", WorkerClass: "junior-developer", Coding: true},
	}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})

	if got["C-BE"].Phase != ActivityConstructionPhase(int(projectstate.ActivityConstructionDone)) {
		t.Errorf("C-BE Phase = %d, want Done (derived from a ledger that passed every gate)", got["C-BE"].Phase)
	}
	if got["C-BE"].BuildStatus != ActivityBuildStatus(int(projectstate.BuildIntegrated)) {
		t.Errorf("C-BE BuildStatus = %d, want Integrated (derived)", got["C-BE"].BuildStatus)
	}
	// C-FE took its binary exit with a ledger that decided nothing: Done, because the exit
	// is the fact, but NOT integrated, because integration is the ledger's claim to make.
	if got["C-FE"].Phase != ActivityConstructionPhase(int(projectstate.ActivityConstructionDone)) {
		t.Errorf("C-FE Phase = %d, want Done (its exit stamp)", got["C-FE"].Phase)
	}
	if got["C-FE"].BuildStatus != ActivityBuildStatus(int(projectstate.BuildInReview)) {
		t.Errorf("C-FE BuildStatus = %d, want InReview — an exit no gate justified is not integration", got["C-FE"].BuildStatus)
	}
}

// The row's coarse BuildStatus/Phase must agree with the very Phases sub-rows emitted
// beside it — both must derive from the SAME ledger-preferred-over-stored resolution.
// Before this fix, the coarse chip read the raw stored r.Phases while the emitted
// Phases read the ledger, so a partial ledger could make the two disagree (task 11
// item 2). Here the stored Construction completion is false, but its codeReview gate
// PASSED, flipping the emitted sub-row to Completed=true; the coarse status must
// track that same flip, not the stored false.
func TestConstructionRowsToContract_CoarseStatusAgreesWithEmittedPhases(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"C-BE": {
			ActivityID: "C-BE",
			StartedAt:  &testExitAt,
			// Every gate but Construction's has passed...
			Attempts: append(serviceLedger(
				projectstate.MethodPhaseRequirements,
				projectstate.MethodPhaseDetailedDesign,
				projectstate.MethodPhaseTestPlan,
				projectstate.MethodPhaseIntegration,
			),
				// ...and so has the codeReview gate, so the emitted Construction sub-row's
				// Completed is true and the coarse chip must track that same flip.
				projectstate.TaskAttempt{AttemptID: "C-BE:codeReview:1", Task: projectstate.TaskCodeReview, Attempt: 1, Outcome: projectstate.OutcomePassed}),
		},
	}
	meta := map[string]projectstate.ActivityItem{"C-BE": {Name: "C-BE", WorkerClass: "junior-developer", Coding: true}}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})["C-BE"]

	if len(got.Phases) != 5 || !got.Phases[3].Completed {
		t.Fatalf("emitted Construction sub-row Completed = %+v, want true (the ledger's codeReview passed)", got.Phases)
	}
	if got.BuildStatus != ActivityBuildStatus(int(projectstate.BuildIntegrated)) {
		t.Errorf("BuildStatus = %d, want Integrated — it must agree with the emitted Phases (both now complete), not the raw stored Construction=false", got.BuildStatus)
	}
	if got.Phase != ActivityConstructionPhase(int(projectstate.ActivityConstructionDone)) {
		t.Errorf("Phase = %d, want Done — it must agree with the emitted Phases", got.Phase)
	}
}

// A row with a LEDGER and no stored phases must not render "Not started / In
// construction". resolvedPhaseCompletions used to early-return nil on an empty stored
// phase set, but the coarse chip was still derived from that empty set and emitted as a
// real, non-omitempty NAMED ZERO — phase=notStarted, buildStatus=in-construction — for
// 24 of the 25 rows the backfill touched: four passed attempts under a chip saying the
// work had not started. The skeleton now comes from ProfileFor, which is deterministic
// (not render-time synthesis) and is what spec §7.1 means by "the phase rows always
// exist and only their state is unknown".
func TestConstructionRowsToContract_LedgerWithNoStoredPhasesMaterializesTheProfile(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"C-BE": {
			ActivityID: "C-BE",
			// No Phases at all — exactly the 24 backfilled rows.
			Attempts: []projectstate.TaskAttempt{
				{AttemptID: "C-BE:designReview:1", Task: projectstate.TaskDesignReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
				{AttemptID: "C-BE:codeReview:1", Task: projectstate.TaskCodeReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
			},
		},
	}
	meta := map[string]projectstate.ActivityItem{"C-BE": {Name: "C-BE", WorkerClass: "junior-developer", Coding: true}}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})["C-BE"]

	if len(got.Phases) != 5 {
		t.Fatalf("Phases len = %d, want the Service profile's 5 rows materialized from the ledger's row", len(got.Phases))
	}
	if !got.Phases[1].Completed || !got.Phases[3].Completed {
		t.Errorf("detailedDesign/construction Completed = %v/%v, want true/true — both gates passed",
			got.Phases[1].Completed, got.Phases[3].Completed)
	}
	if got.Phases[0].Completed || got.Phases[2].Completed || got.Phases[4].Completed {
		t.Errorf("requirements/testPlan/integration must stay incomplete — the ledger has no gate attempt for them, got %+v", got.Phases)
	}
	// The coarse chip must now be justified by the sub-rows beside it rather than by a
	// named zero value: some phases done, not all → Running / InReview.
	if got.Phase != ActivityConstructionPhase(int(projectstate.ActivityConstructionRunning)) {
		t.Errorf("Phase = %d, want Running — a row with four passed attempts is not 'Not started'", got.Phase)
	}
	if got.BuildStatus != ActivityBuildStatus(int(projectstate.BuildInReview)) {
		t.Errorf("BuildStatus = %d, want InReview — Construction's gate passed but Integration's has not", got.BuildStatus)
	}
}

// Spec MUST-fix D-gspa (a): when a row's stored phases[] disagrees with its classified
// type's PROFILE, the profile wins. The fixture row — a ui-designer, noncoding additive —
// classifies as uiDesign (two phases, 40/60) yet stores five SERVICE phases with Service
// weights (15/20/10/40/15), the zero-value set a row the dispatcher never stamped is
// seeded with: three phases the uiDesign profile does not have. Two fields on one row
// giving contradictory answers with no rule on the wire for which wins is what this
// stage exists to remove: the profile is derived from the committed architecture, the
// stored slice only supplies state.
func TestConstructionRowsToContract_ProfileWinsOverAContradictoryStoredPhaseSet(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"N-UI-CONCEPT": {
			ActivityID: "N-UI-CONCEPT",
			Attempts:   allServiceLedger(), // five Service phases, Service weights
		},
	}
	meta := map[string]projectstate.ActivityItem{"N-UI-CONCEPT": {Name: "N-UI-CONCEPT", WorkerClass: "ui-designer", Coding: false}}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})["N-UI-CONCEPT"]

	if got.Type != ActivityType(int(projectstate.ActivityTypeUIDesign)) {
		t.Fatalf("Type = %d, want uiDesign — the fixture's whole point", got.Type)
	}
	if len(got.Phases) != 2 {
		t.Fatalf("Phases = %+v, want the uiDesign profile's TWO rows, not the five stored Service phases", got.Phases)
	}
	if got.Phases[0].Weight != 40 || got.Phases[1].Weight != 60 {
		t.Errorf("weights = %d/%d, want the uiDesign profile's 40/60, not Service's", got.Phases[0].Weight, got.Phases[1].Weight)
	}
	for _, ph := range got.Phases {
		if ph.Phase == ActivityMethodPhase(string(projectstate.MethodPhaseConstruction)) ||
			ph.Phase == ActivityMethodPhase(string(projectstate.MethodPhaseTestPlan)) ||
			ph.Phase == ActivityMethodPhase(string(projectstate.MethodPhaseIntegration)) {
			t.Errorf("phase %q survived from the stored slice — the uiDesign profile does not carry it", ph.Phase)
		}
	}
	// The state the profile DOES carry still comes from storage.
	if !got.Phases[0].Completed || !got.Phases[1].Completed {
		t.Errorf("stored completions for the profile's own phases must survive, got %+v", got.Phases)
	}
}

// worstOrigin is an aggregate over the ledger, and over an EMPTY ledger it is the seed
// value "observed" — correct as an aggregate (nothing was derived from anything
// unknown), a trap read alone at row level: it says "recorded" about a row where
// nothing was recorded. A RECORDED row still carries it (the contract describes it as
// meaningless over an empty ledger, and that description reaches the MCP schema); only
// an unrecorded, planned-no-record row omits it. This pins the pairing the SPA's
// omission rule depends on — the stamp is only ever meaningful accompanied by attempts.
func TestConstructionRowsToContract_WorstOriginIsOnlyMeaningfulWithALedger(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		// Empty ledger: the emitted stamp is the aggregate seed, NOT an observation.
		"C-EMPTY": {ActivityID: "C-EMPTY", StartedAt: &testExitAt},
		// A real ledger with one synthesized attempt: the stamp is a real roll-up.
		"C-LEDGER": {
			ActivityID: "C-LEDGER",
			Attempts: []projectstate.TaskAttempt{
				{AttemptID: "C-LEDGER:codeReview:1", Task: projectstate.TaskCodeReview, Attempt: 1,
					Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginObserved}},
				{AttemptID: "C-LEDGER:construction:1", Task: projectstate.TaskConstruction, Attempt: 1,
					Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginSynthesized}},
			},
		},
	}
	meta := map[string]projectstate.ActivityItem{
		"C-EMPTY":  {Name: "C-EMPTY", WorkerClass: "junior-developer", Coding: true},
		"C-LEDGER": {Name: "C-LEDGER", WorkerClass: "junior-developer", Coding: true},
	}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})

	if n := len(got["C-EMPTY"].Attempts); n != 0 {
		t.Fatalf("C-EMPTY Attempts len = %d, want 0 — the fixture's whole point", n)
	}
	if o := got["C-EMPTY"].WorstOrigin; o == nil || *o != string(projectstate.OriginObserved) {
		t.Errorf("C-EMPTY WorstOrigin = %v, want the aggregate seed %q — and consumers must suppress it, since no attempt was ever observed",
			o, projectstate.OriginObserved)
	}
	if o := got["C-LEDGER"].WorstOrigin; o == nil || *o != string(projectstate.OriginSynthesized) {
		t.Errorf("C-LEDGER WorstOrigin = %v, want %q — one synthesized attempt taints the roll-up",
			o, projectstate.OriginSynthesized)
	}
}

// A CLASSIFIED row with neither stored phases nor an attempt ledger resolves to nil
// completions, so CoarseBuildStatusFor returns its zero value BuildInConstruction — a
// positive claim ("this is being built") about work that has not begun. The wire field
// is required and its zero is a real, named member, so honesty is expressed by a
// COMPANION FLAG the consumer gates on, exactly as classified gates kind/status/
// currentLifecyclePhase and a non-empty ledger gates worstOrigin.
//
// hasBuildEvidence is deliberately NOT the same thing as classified: this row IS
// classified — the server knows exactly what it is — it simply has no record of any
// progress. Folding the two together would be the second conflation this stage exists
// to remove.
func TestConstructionRowsToContract_NoEvidenceAssertsNoBuildStatus(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		// Neither stored phases nor a ledger: nothing to resolve, nothing to assert.
		"C-x": {ActivityID: "C-x"},
		// Stored phases: evidence, even though every phase is still incomplete.
		"C-STORED": {ActivityID: "C-STORED", Attempts: allServiceLedger()},
		// A ledger with no stored phases: also evidence (the profile materializes).
		"C-LEDGER": {
			ActivityID: "C-LEDGER",
			Attempts: []projectstate.TaskAttempt{
				{AttemptID: "C-LEDGER:construction:1", Task: projectstate.TaskConstruction, Attempt: 1,
					Outcome: projectstate.OutcomePassed},
			},
		},
	}
	meta := map[string]projectstate.ActivityItem{
		"C-x":      {Name: "C-x", WorkerClass: "junior-developer", Coding: true},
		"C-STORED": {Name: "C-STORED", WorkerClass: "junior-developer", Coding: true},
		"C-LEDGER": {Name: "C-LEDGER", WorkerClass: "junior-developer", Coding: true},
	}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})

	row := got["C-x"]
	if !row.Classified {
		t.Fatalf("fixture should classify; got Classified=false")
	}
	if row.HasBuildEvidence {
		t.Errorf("HasBuildEvidence = true for a row with no phases and no attempts")
	}
	if len(row.Phases) != 0 {
		t.Errorf("C-x Phases len = %d, want 0 — the flag must track the resolved set", len(row.Phases))
	}
	if !got["C-STORED"].HasBuildEvidence {
		t.Errorf("C-STORED HasBuildEvidence = false; stored phases ARE evidence")
	}
	if !got["C-LEDGER"].HasBuildEvidence {
		t.Errorf("C-LEDGER HasBuildEvidence = false; an attempt ledger IS evidence")
	}
}

// An UNCLASSIFIED row cannot have build evidence either: classifiedRowView returns nil
// completions for it, and the row already asserts nothing about type or status. The two
// flags are independent in meaning but this pairing must hold — hasBuildEvidence must
// never be true where Phases is empty, or a consumer gating on it would surface the
// zero-value chip again through the other door.
func TestConstructionRowsToContract_UnclassifiedRowHasNoBuildEvidence(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"ZZ-mystery": {ActivityID: "ZZ-mystery", Attempts: allServiceLedger()},
	}
	got := constructionRowsToContract(rows, map[string]projectstate.ActivityItem{}, nil, constructionPlan{})
	row := got["ZZ-mystery"]
	if row.Classified {
		t.Fatalf("fixture should NOT classify; got Classified=true")
	}
	if row.HasBuildEvidence {
		t.Errorf("HasBuildEvidence = true on an unclassified row, whose Phases are suppressed")
	}
}

// The committed activity list is authoritative for what exists: a listed activity with
// no stored head-state is still emitted, as a PLANNED-NO-RECORD row — classified by the
// server (so the SPA can draw its profile's phases and tasks) yet asserting no evidence,
// no phase completions and no attempts. Before this, an activity nobody had touched was
// absent from the view altogether rather than shown as not started. The merge must not
// disturb a stored row, and nothing stored plus nothing listed is still nil.
func TestConstructionRowsToContract_ListedActivityWithNoRowIsPlannedNoRecord(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"C-BE": {ActivityID: "C-BE", Attempts: allServiceLedger()},
	}
	meta := map[string]projectstate.ActivityItem{
		"C-BE":   {Name: "C-BE", WorkerClass: "junior-developer", Coding: true},
		"C-PLAN": {Name: "C-PLAN", WorkerClass: "junior-developer", Coding: true},
		"N-IT":   {Name: "N-IT", WorkerClass: "software-tester", Coding: false},
	}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})
	if len(got) != 3 {
		t.Fatalf("len(got) = %d, want 3 (one stored row + two listed-with-no-row)", len(got))
	}
	for _, id := range []string{"C-PLAN", "N-IT"} {
		r, ok := got[id]
		if !ok {
			t.Fatalf("%s: a listed activity with no stored row is missing from the view", id)
		}
		if r.ActivityID != id {
			t.Errorf("%s: ActivityID = %q, want the listed id", id, r.ActivityID)
		}
		if !r.Classified {
			t.Errorf("%s: Classified = false; the server classifies a listed activity from its metadata", id)
		}
		if r.HasBuildEvidence {
			t.Errorf("%s: HasBuildEvidence = true on a row with no record at all", id)
		}
		if len(r.Phases) != 0 {
			t.Errorf("%s: Phases = %d, want none (no stored phases, no ledger)", id, len(r.Phases))
		}
		if len(r.Attempts) != 0 {
			t.Errorf("%s: Attempts = %d, want none", id, len(r.Attempts))
		}
	}
	if got["C-PLAN"].Type != ActivityType(int(projectstate.ActivityTypeService)) {
		t.Errorf("C-PLAN Type = %d, want Service", got["C-PLAN"].Type)
	}
	if got["N-IT"].Type != ActivityType(int(projectstate.ActivityTypeTesting)) ||
		got["N-IT"].Variant != TestingVariant(int(projectstate.TestVariantSystemTest)) {
		t.Errorf("N-IT Type/Variant = %d/%d, want Testing/SystemTest", got["N-IT"].Type, got["N-IT"].Variant)
	}
	if !got["C-BE"].HasBuildEvidence || len(got["C-BE"].Phases) == 0 {
		t.Errorf("the stored C-BE row lost its evidence in the merge")
	}
	if out := constructionRowsToContract(nil, map[string]projectstate.ActivityItem{}, nil, constructionPlan{}); out != nil {
		t.Errorf("nothing stored and nothing listed = %d rows, want nil", len(out))
	}
}

// Recorded is the one explicit wire signal that a stored head-state row backs a row:
// a planned-no-record row (listed, nothing stored) says Recorded=false and omits
// worstOrigin — whose empty-ledger seed would otherwise read "observed" about a row
// where nothing was recorded — while a stored row, even one with no ledger, says
// Recorded=true and carries it. Without the flag an MCP reader has only the zero
// BuildStatus (InConstruction) to go on and reports unstarted work as in progress.
func TestConstructionRowsToContract_PlannedNoRecordRowIsUnrecordedAndCarriesNoOrigin(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"C-BE":    {ActivityID: "C-BE", Attempts: allServiceLedger()},
		"C-EMPTY": {ActivityID: "C-EMPTY"},
	}
	meta := map[string]projectstate.ActivityItem{
		"C-BE":    {Name: "C-BE", WorkerClass: "junior-developer", Coding: true},
		"C-EMPTY": {Name: "C-EMPTY", WorkerClass: "junior-developer", Coding: true},
		"C-PLAN":  {Name: "C-PLAN", WorkerClass: "junior-developer", Coding: true},
		"N-IT":    {Name: "N-IT", WorkerClass: "software-tester", Coding: false},
	}
	got := constructionRowsToContract(rows, meta, nil, constructionPlan{})
	for id, want := range map[string]bool{"C-BE": true, "C-EMPTY": true, "C-PLAN": false, "N-IT": false} {
		r := got[id]
		if r.Recorded != want {
			t.Errorf("%s: Recorded = %v, want %v", id, r.Recorded, want)
		}
		if hasOrigin := r.WorstOrigin != nil; hasOrigin != want {
			t.Errorf("%s: worstOrigin present = %v, want %v (present iff recorded)", id, hasOrigin, want)
		}
	}
}

// Exercised through the actual mapper (constructionRowsToContract) rather than the pure
// function: each row is drawn in the layer of its OWN component, joined through the
// activity's componentId. The client app names the client it builds, so it lands on the
// Client row even though it depends on managers; a componentless row lands in the
// project-wide band.
func TestConstructionRowsToContract_RowTakesItsComponentsLayer(t *testing.T) {
	rows := map[string]projectstate.ActivityExecution{
		"U-SPA-web-client":  {ActivityID: "U-SPA-web-client"},
		"C-billing-manager": {ActivityID: "C-billing-manager"},
		"N-IT":              {ActivityID: "N-IT"},
	}
	meta := map[string]projectstate.ActivityItem{
		"U-SPA-web-client":  {Name: "U-SPA-web-client", WorkerClass: "junior-developer", Coding: true, ComponentID: "web-client"},
		"C-billing-manager": {Name: "C-billing-manager", WorkerClass: "junior-developer", Coding: true, ComponentID: "billing-manager"},
		"N-IT":              {Name: "N-IT", WorkerClass: "software-tester", Coding: false},
	}
	componentLayer := map[string]string{"billing-manager": "manager", "web-client": "client"}
	got := constructionRowsToContract(rows, meta, componentLayer, constructionPlan{})

	if l, b := got["U-SPA-web-client"].Layer, got["U-SPA-web-client"].LayerBand; l != "client" || b != "layered" {
		t.Errorf("U-SPA-web-client Layer/LayerBand = %q/%q, want client/layered", l, b)
	}
	if l, b := got["C-billing-manager"].Layer, got["C-billing-manager"].LayerBand; l != "manager" || b != "layered" {
		t.Errorf("C-billing-manager Layer/LayerBand = %q/%q, want manager/layered", l, b)
	}
	if l, b := got["N-IT"].Layer, got["N-IT"].LayerBand; l != "" || b != "projectWide" {
		t.Errorf("N-IT Layer/LayerBand = %q/%q, want \"\"/projectWide", l, b)
	}
}

// componentLayerByID must tolerate an uncommitted system design exactly as
// activityMetaByID tolerates a missing activity list — an empty map, not a panic or a
// fabricated layer.
func TestComponentLayerByID_TolerantOfMissingSystemDesign(t *testing.T) {
	if got := componentLayerByID(projectstate.Project{}); len(got) != 0 {
		t.Errorf("componentLayerByID(no system design) = %v, want empty map", got)
	}
}

// componentLayerByID projects the committed System's components by id, rendering each
// Layer enum through its canonical wire string (Layer.String()) — the same lowercase
// vocabulary LayerForActivity's componentLayer parameter expects.
func TestComponentLayerByID_ProjectsCommittedComponents(t *testing.T) {
	p := projectstate.Project{
		SystemDesign: projectstate.ArtifactSlot{
			Model: &projectstate.System{
				Components: []projectstate.Component{
					{ID: "billing-manager", Layer: projectstate.LayerManager},
					{ID: "billing-api", Layer: projectstate.LayerClient},
				},
			},
		},
	}
	got := componentLayerByID(p)
	if got["billing-manager"] != "manager" {
		t.Errorf("billing-manager layer = %q, want manager", got["billing-manager"])
	}
	if got["billing-api"] != "client" {
		t.Errorf("billing-api layer = %q, want client", got["billing-api"])
	}
}

// The EV/SPI curve and the build status rendered beside it must be read off the SAME
// derivation. computeEVAtRead used to select the integrated set from the RAW stored
// BuildStatus, so the curve could contradict the status on the same screen.
func TestComputeEVAtRead_UsesTheDerivedIntegratedSet(t *testing.T) {
	var captured []string
	est := &estimationfake.FakeEstimationEngine{
		ComputeEarnedValueFn: func(_ fweng.Context, _ estimation.ActivityList, _ estimation.Network, integrated []string, _ int64, _ int64) (estimation.EVCurve, error) {
			captured = append([]string(nil), integrated...)
			return estimation.EVCurve{}, nil
		},
	}
	m := &systemDesignManager{estimator: est}
	// A frozen service contract classifies the row as Service, whose profile is the
	// canonical five — so "every phase complete" means all five, exactly as the
	// list view beside the curve renders it.
	contract := []projectstate.ProducedArtifact{{Kind: "service-contract"}}
	p := projectstate.Project{ActivityExecution: map[string]projectstate.ActivityExecution{
		// Stored InConstruction, every phase complete → derived Integrated.
		"C-BE": {
			ActivityID: "C-BE",
			Produced:   contract,
			Attempts:   allServiceLedger(),
		},
		// Stored Integrated, nothing complete → derived InConstruction.
		"C-FE": {
			ActivityID: "C-FE",
			Produced:   contract,
			Attempts:   openLedger(),
		},
		// UNCLASSIFIED, stored Integrated, every phase complete. It must not reach the
		// curve at all: the row beside it refuses to assert a build status, so a curve
		// that counts it contradicts the very screen it is drawn on.
		"C-??": {
			ActivityID: "C-??",
			Attempts:   allServiceLedger(),
		},
	}}

	m.computeEVAtRead(p, 4)

	if len(captured) != 1 || captured[0] != "C-BE" {
		t.Errorf("integrated set = %v, want [C-BE] — the curve must read the derived status over the classified rows only, not the stored one", captured)
	}
}

// The rule is decided PER PHASE. A partial ledger says NOTHING about a phase whose gate
// task it never wrote, and the phase materializes as an honest unknown — rendered as
// not-yet-complete — rather than borrowing another phase's verdict.
func TestPhasesToContract_PartialLedgerDoesNotDenySilentPhases(t *testing.T) {
	// A partial ledger: it has an opinion about detailedDesign and construction only.
	// testPlan and integration have no gate attempt at all.
	attempts := []projectstate.TaskAttempt{
		{AttemptID: "U-SPA-web-client:designReview:1", Task: projectstate.TaskDesignReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
		{AttemptID: "U-SPA-web-client:codeReview:1", Task: projectstate.TaskCodeReview, Attempt: 1, Outcome: projectstate.OutcomePassed},
	}
	// The Frontend profile's row set — requirements first, which the stored slice does
	// not carry and the ledger says nothing about. A NON-MONOTONIC shape: an incomplete
	// first phase under four complete ones.
	got := phasesToContract(resolvedPhaseCompletions(projectstate.ProfileFor(projectstate.ActivityTypeFrontend, 0), attempts))
	if len(got) != 5 {
		t.Fatalf("phasesToContract len = %d, want 5", len(got))
	}
	if got[0].Phase != ActivityMethodPhase(string(projectstate.MethodPhaseRequirements)) || got[0].Completed {
		t.Errorf("requirements = %+v, want an INCOMPLETE first row — neither storage nor the ledger records it", got[0])
	}
	for i, want := range []struct {
		phase     projectstate.ActivityMethodPhase
		completed bool
		why       string
	}{
		{projectstate.MethodPhaseDetailedDesign, true, "its designReview passed"},
		{projectstate.MethodPhaseTestPlan, false, "the ledger has no stpReview attempt, and there is no stored flag left to stand in for one"},
		{projectstate.MethodPhaseConstruction, true, "its codeReview passed"},
		{projectstate.MethodPhaseIntegration, false, "the ledger has no testing attempt"},
	} {
		idx := i + 1
		if got[idx].Phase != ActivityMethodPhase(string(want.phase)) {
			t.Fatalf("phase %d = %q, want %q", idx, got[idx].Phase, want.phase)
		}
		if got[idx].Completed != want.completed {
			t.Errorf("%s Completed = %v, want %v — %s", want.phase, got[idx].Completed, want.completed, want.why)
		}
	}
}

// The other half of the per-phase rule: where the ledger DOES have an opinion, a rejected
// latest gate leaves its phase incomplete.
func TestPhasesToContract_PartialLedgerStillDeniesARejectedGate(t *testing.T) {
	attempts := []projectstate.TaskAttempt{
		{AttemptID: "C-x:designReview:1", Task: projectstate.TaskDesignReview, Attempt: 1, Outcome: projectstate.OutcomeRejected},
	}
	// Documentation's profile: detailedDesign(0), construction(1), integration(2).
	got := phasesToContract(resolvedPhaseCompletions(projectstate.ProfileFor(projectstate.ActivityTypeDocumentation, 0), attempts))
	if len(got) != 3 {
		t.Fatalf("phasesToContract len = %d, want 3", len(got))
	}
	if got[0].Completed {
		t.Errorf("detailedDesign Completed = true, want false — its only designReview was rejected")
	}
	if got[2].Completed {
		t.Errorf("integration Completed = true, want false — the ledger says nothing about it, and nothing else speaks for it")
	}
}

// constructionStartedFor decides Begin versus Resume once, on the server, from the
// STORED head-state: pump-written state or an OBSERVED attempt. The load-bearing case
// is the live corpus's own shape — 23 stored rows carrying nothing but backfilled
// attempts — which must read NOT started: counting reconstructed work is exactly how
// the console came to say "Resume" on a project whose pump had never run.
func TestConstructionStartedFor(t *testing.T) {
	now := time.Now()
	reconstructed := func(o projectstate.RecordOrigin) []projectstate.TaskAttempt {
		return []projectstate.TaskAttempt{
			{Provenance: projectstate.AttemptProvenance{Origin: o, Basis: "b"}},
			{Provenance: projectstate.AttemptProvenance{Origin: o, Basis: "b"}},
		}
	}
	cases := []struct {
		name string
		rows map[string]projectstate.ActivityExecution
		want bool
	}{
		{"nothing stored", nil, false},
		{"backfilled attempts only (the live corpus)", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", Attempts: reconstructed(projectstate.OriginBackfilled)},
			"C-b": {ActivityID: "C-b", Attempts: reconstructed(projectstate.OriginBackfilled)},
		}, false},
		{"synthesized attempts only", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", Attempts: reconstructed(projectstate.OriginSynthesized)},
		}, false},
		{"a stored row with nothing on it", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a"},
		}, false},
		{"a start time", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", StartedAt: &now},
		}, true},
		{"a coarse phase past NotStarted", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", StartedAt: &testExitAt},
		}, true},
		{"an exit stamp", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", CompletedAt: &testExitAt},
		}, true},
		{"a recorded failure reason", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", FailureReason: projectstate.PipelineFailed},
		}, true},
		{"a recorded failure detail", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", FailureDetail: "pipeline cancelled"},
		}, true},
		{"operator notes only (plan B1.1: a note is not pump state)", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", OperatorNotes: []projectstate.OperatorNote{{NoteID: "n", Kind: projectstate.NoteSendBack, Text: "x", RecordedAt: now}}},
		}, false},
		{"one observed attempt among backfilled ones", map[string]projectstate.ActivityExecution{
			"C-a": {ActivityID: "C-a", Attempts: append(reconstructed(projectstate.OriginBackfilled),
				projectstate.TaskAttempt{Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginObserved}})},
		}, true},
	}
	for _, c := range cases {
		if got := constructionStartedFor(c.rows); got != c.want {
			t.Errorf("%s: constructionStartedFor = %v, want %v", c.name, got, c.want)
		}
	}
}

// The field reaches the get-project view-model the SPA and the MCP tool read.
func TestProjectStateToContract_CarriesConstructionStarted(t *testing.T) {
	m := &systemDesignManager{}
	now := time.Now()
	started := projectstate.Project{ActivityExecution: map[string]projectstate.ActivityExecution{
		"C-a": {ActivityID: "C-a", StartedAt: &now},
	}}
	if !m.projectStateToContract(started).ConstructionStarted {
		t.Errorf("a project with a started row reads ConstructionStarted=false")
	}
	backfilledOnly := projectstate.Project{ActivityExecution: map[string]projectstate.ActivityExecution{
		"C-a": {ActivityID: "C-a", Attempts: []projectstate.TaskAttempt{
			{Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginBackfilled, Basis: "b"}},
		}},
	}}
	if m.projectStateToContract(backfilledOnly).ConstructionStarted {
		t.Errorf("a project whose only evidence is backfilled reads ConstructionStarted=true")
	}
}

// TestProjectStateToContract_CarriesTheRecordedPause (B1.7): get-project carries the
// recorded operator pause as stored — the console offers Resume in Begin's place while it
// holds — and omits the reason when there is none.
func TestProjectStateToContract_CarriesTheRecordedPause(t *testing.T) {
	m := &systemDesignManager{}
	paused := m.projectStateToContract(projectstate.Project{OperatorPaused: true, PauseReason: "operator halt"})
	if !paused.OperatorPaused || paused.PauseReason == nil || *paused.PauseReason != "operator halt" {
		t.Fatalf("a paused project reads OperatorPaused=%v PauseReason=%v", paused.OperatorPaused, paused.PauseReason)
	}
	running := m.projectStateToContract(projectstate.Project{})
	if running.OperatorPaused || running.PauseReason != nil {
		t.Fatalf("an unpaused project reads OperatorPaused=%v PauseReason=%v", running.OperatorPaused, running.PauseReason)
	}
}

// pendingLedger is a backfill-shaped attempt ledger: one passed attempt per lifecycle
// node task (work, then gate) of each named phase, attempt 1, passed.
func pendingLedger(activityID string, phases ...projectstate.ActivityMethodPhase) []projectstate.TaskAttempt {
	var out []projectstate.TaskAttempt
	for _, ph := range phases {
		for _, task := range []projectstate.MethodTask{
			projectstate.AgentTaskFor(ph), projectstate.GateTaskFor(ph),
		} {
			out = append(out, projectstate.TaskAttempt{
				AttemptID:  projectstate.AttemptID(activityID, task, 1),
				Task:       task,
				Phase:      projectstate.PhaseForTask(task),
				Attempt:    1,
				Outcome:    projectstate.OutcomePassed,
				Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginBackfilled, Basis: "test fixture"},
			})
		}
	}
	return out
}

// TestConstructionRowsToContract_PendingResume pins architect (D), D.3 on the shape of
// the committed integration-pending rows (62efcafe): a row no pump wrote whose ledger
// holds every phase but Integration carries pendingResume, resuming at integration and
// waiting on exactly its unsatisfied direct dependencies — in authored order, each with
// its reason, and never a satisfied one. Every other population carries none.
func TestConstructionRowsToContract_PendingResume(t *testing.T) {
	svc := func(name string) projectstate.ActivityItem {
		return projectstate.ActivityItem{Name: name, WorkerClass: "junior-developer", Coding: true}
	}
	all := projectstate.ProfileFor(projectstate.ActivityTypeService, projectstate.TestVariantPlan).PhaseIDs()
	fourOfFive := all[:len(all)-1]
	ids := []string{"C-billing-manager", "C-billing-engine", "C-billing-state-access", "C-merchant-gateway-access",
		"C-operations-manager", "C-next", "C-live", "C-live-phases", "C-both", "C-done", "C-planned"}
	meta := map[string]projectstate.ActivityItem{}
	for _, id := range ids {
		meta[id] = svc(id)
	}
	started := time.Date(2026, 9, 13, 0, 0, 0, 0, time.UTC)
	rows := map[string]projectstate.ActivityExecution{
		"C-billing-manager":    {ActivityID: "C-billing-manager", Attempts: pendingLedger("C-billing-manager", fourOfFive...)},
		"C-billing-engine":     {ActivityID: "C-billing-engine", Attempts: pendingLedger("C-billing-engine", all...)},
		"C-operations-manager": {ActivityID: "C-operations-manager", Attempts: pendingLedger("C-operations-manager", fourOfFive...)},
		"C-next":               {ActivityID: "C-next", Attempts: pendingLedger("C-next", fourOfFive...)},
		// Pump-written: a stored Running with its start stamp — in flight, not pending.
		"C-live": {ActivityID: "C-live", StartedAt: &started},
		// Pump-written mid-lifecycle: a start stamp over a ledger that has decided some
		// phases and not others. Only the PumpWroteRow clause keeps it from reading
		// pending — nothing about its ledger says so.
		"C-live-phases": {ActivityID: "C-live-phases", StartedAt: &started,
			Attempts: serviceLedger(projectstate.MethodPhaseRequirements)},
		// A start stamp plus a partial ledger: the pump wrote it, so it is not pending.
		"C-both": {ActivityID: "C-both", StartedAt: &started,
			Attempts: pendingLedger("C-both", fourOfFive...)},
		"C-done": {ActivityID: "C-done", Attempts: pendingLedger("C-done", all...)},
	}
	plan := constructionPlan{
		depsByActivity: map[string][]string{
			"C-billing-manager": {"C-billing-engine", "C-billing-state-access", "M-gate", "C-merchant-gateway-access", "C-operations-manager", "M-start", "ghost"},
			"C-next":            {"C-billing-engine", "M-start"},
			"C-live":            {"C-billing-state-access"},
			"C-both":            {"C-billing-state-access"},
		},
		milestones: projectstate.MilestonesByID(&projectstate.Network{Milestones: []projectstate.NetworkMilestone{
			{ID: "M-start"},
			{ID: "M-gate", DependsOn: []string{"C-billing-state-access"}},
		}}),
	}
	got := constructionRowsToContract(rows, meta, nil, plan)

	pr := got["C-billing-manager"].PendingResume
	if pr == nil {
		t.Fatal("C-billing-manager: pendingResume = nil, want the integration-pending read")
	}
	if pr.FromPhase != ActivityMethodPhase(string(projectstate.MethodPhaseIntegration)) {
		t.Errorf("FromPhase = %q, want integration", pr.FromPhase)
	}
	want := []PendingDependency{
		{Id: "C-billing-state-access", Reason: "notBuilt"},
		{Id: "M-gate", Reason: "milestoneNotReached"},
		{Id: "C-merchant-gateway-access", Reason: "notBuilt"},
		{Id: "C-operations-manager", Reason: "builtNotIntegrated"},
		{Id: "ghost", Reason: "unresolved"},
	}
	if !slices.Equal(pr.WaitsOn, want) {
		t.Errorf("WaitsOn = %+v\nwant     %+v", pr.WaitsOn, want)
	}

	next := got["C-next"].PendingResume
	if next == nil || next.WaitsOn == nil || len(next.WaitsOn) != 0 {
		t.Fatalf("C-next: pendingResume = %+v, want next in line with an empty, non-nil waitsOn", next)
	}
	raw, err := json.Marshal(got["C-next"])
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(raw), `"pendingResume":{"fromPhase":"integration","waitsOn":[]}`) {
		t.Errorf("next in line must serialize an empty waitsOn array, got %s", raw)
	}

	for _, id := range []string{"C-live", "C-live-phases", "C-both", "C-done", "C-planned", "C-billing-engine"} {
		if got[id].PendingResume != nil {
			t.Errorf("%s: pendingResume = %+v, want omitted (not started, pump-written, or done)", id, got[id].PendingResume)
		}
	}
	raw, err = json.Marshal(got["C-planned"])
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(raw), "pendingResume") {
		t.Errorf("a row with no pendingResume must omit the key, got %s", raw)
	}
}

// TestConstructionRowsToContract_PendingResumeNeedsARunningLedger pins isPendingResume's
// predicate: a row no pump wrote is integration-pending only when its ledger makes it
// effectively RUNNING (some phase complete, not all). "Not Done" is a weaker rule that
// the committed rows cannot tell apart from it, since every ledger there is 4/5 or 5/5
// passed. These fixtures can: a row no pump wrote whose ledger completes NO phase is
// effectively NotStarted, and must read neither pending nor "built but not integrated"
// to a dependent.
//   - C-failed-ledger: the Requirements tasks ran once, and the gate FAILED.
//   - C-rejected-gate: a PARTIAL ledger (Requirements only) whose gate passed on its
//     first round and was REJECTED on its second, the latest, so no phase is complete.
func TestConstructionRowsToContract_PendingResumeNeedsARunningLedger(t *testing.T) {
	svc := func(name string) projectstate.ActivityItem {
		return projectstate.ActivityItem{Name: name, WorkerClass: "junior-developer", Coding: true}
	}
	all := projectstate.ProfileFor(projectstate.ActivityTypeService, projectstate.TestVariantPlan).PhaseIDs()
	gate := projectstate.GateTaskFor(projectstate.MethodPhaseRequirements)
	if gate == "" {
		t.Fatal("Requirements has no gate task; the fixtures below need one")
	}
	withGate := func(id string, outcomes ...projectstate.TaskOutcome) []projectstate.TaskAttempt {
		ledger := pendingLedger(id, projectstate.MethodPhaseRequirements)
		var out []projectstate.TaskAttempt
		for _, a := range ledger {
			if a.Task != gate {
				out = append(out, a)
			}
		}
		for i, o := range outcomes {
			n := i + 1
			out = append(out, projectstate.TaskAttempt{
				AttemptID:  projectstate.AttemptID(id, gate, n),
				Task:       gate,
				Phase:      projectstate.MethodPhaseRequirements,
				Attempt:    n,
				Outcome:    o,
				Provenance: projectstate.AttemptProvenance{Origin: projectstate.OriginBackfilled, Basis: "test fixture"},
			})
		}
		return out
	}
	ids := []string{"C-failed-ledger", "C-rejected-gate", "C-waiter"}
	meta := map[string]projectstate.ActivityItem{}
	for _, id := range ids {
		meta[id] = svc(id)
	}
	rows := map[string]projectstate.ActivityExecution{
		"C-failed-ledger": {ActivityID: "C-failed-ledger", Attempts: withGate("C-failed-ledger", projectstate.OutcomeFailed)},
		"C-rejected-gate": {ActivityID: "C-rejected-gate",
			Attempts: withGate("C-rejected-gate", projectstate.OutcomePassed, projectstate.OutcomeRejected)},
		// Integration-pending, waiting on both: they are not built, and neither is
		// "built but not integrated" (which is what an integration-pending row is).
		"C-waiter": {ActivityID: "C-waiter", Attempts: pendingLedger("C-waiter", all[:len(all)-1]...)},
	}
	for _, id := range []string{"C-failed-ledger", "C-rejected-gate"} {
		if effective, _ := projectstate.EffectiveConstructionPhase(rows[id], meta[id]); effective != projectstate.ActivityConstructionNotStarted {
			t.Fatalf("%s: the fixture must be effectively NotStarted, got %v", id, effective)
		}
	}
	plan := constructionPlan{depsByActivity: map[string][]string{"C-waiter": {"C-failed-ledger", "C-rejected-gate"}}}
	got := constructionRowsToContract(rows, meta, nil, plan)

	for _, id := range []string{"C-failed-ledger", "C-rejected-gate"} {
		if got[id].PendingResume != nil {
			t.Errorf("%s: pendingResume = %+v, want omitted: its ledger completes no phase, so it is not started, not pending", id, got[id].PendingResume)
		}
	}
	pr := got["C-waiter"].PendingResume
	if pr == nil {
		t.Fatal("C-waiter: pendingResume = nil, want integration-pending")
	}
	want := []PendingDependency{
		{Id: "C-failed-ledger", Reason: "notBuilt"},
		{Id: "C-rejected-gate", Reason: "notBuilt"},
	}
	if !slices.Equal(pr.WaitsOn, want) {
		t.Errorf("C-waiter WaitsOn = %+v\nwant           %+v", pr.WaitsOn, want)
	}
}

// Operator notes (plan B1.1) reach the wire row exactly as stored: recorded order, the
