// pdRegisterGenActivityExecution registers the six ROUND-LEDGER activities the design rails
// read and dual-write through, under the names the generated RegisterWorker uses in
// production. It is called from pdRegisterGenActivities so EVERY workflow test has them: the
// dual-write is unconditional behind the fence, and a test env missing them would exercise
// the best-effort miss path instead of the feature.
func pdRegisterGenActivityExecution(env *testsuite.TestWorkflowEnvironment, ps projectstate.ProjectStateAccess) {
	base, ok := ps.(pdExecLedgerBase)
	if !ok {
		return
	}
	acts := &genActivities{ActivityExecution: pdFakeActivityExecution{base.baseProjectState()}}
	env.RegisterActivityWithOptions(acts.ActivityExecutionReadActivityExecution, activity.RegisterOptions{Name: "activityExecutionAccess.readActivityExecution"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionOpenActivity, activity.RegisterOptions{Name: "activityExecutionAccess.openActivity"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionOpenReviewRound, activity.RegisterOptions{Name: "activityExecutionAccess.openReviewRound"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionAppendReviewVerdict, activity.RegisterOptions{Name: "activityExecutionAccess.appendReviewVerdict"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionDecideReviewRound, activity.RegisterOptions{Name: "activityExecutionAccess.decideReviewRound"})
	env.RegisterActivityWithOptions(acts.ActivityExecutionSetReviewCommentStatus, activity.RegisterOptions{Name: "activityExecutionAccess.setReviewCommentStatus"})
}

// registerName builds the workflow.RegisterOptions naming a registered workflow.
func registerName(name string) workflow.RegisterOptions {
	return workflow.RegisterOptions{Name: name}
}

// pdRegisterCoAuthor registers the per-artifact gate workflow + its activities on the
// test env, exactly as RegisterWorker does in production (same stable names). Every
// Activity is generated (pdRegisterGenActivities); ps is the fake substrate the generated
// projectState/designSession activities are backed by (threaded explicitly — the
// pdWorkflows struct no longer carries an RA dep).
func pdRegisterCoAuthor(env *testsuite.TestWorkflowEnvironment, wf *pdWorkflows, ps projectstate.ProjectStateAccess, pipe *pdFakePipeline, eps ...*fakeEpisodes) {
	env.RegisterWorkflowWithOptions(wf.CoAuthorPhase2ArtifactWorkflow, registerName(pdExecutionKindCoAuthor))
	pdRegisterGenActivities(env, ps, pipe, nil, eps...)
}

// ---- Pure unit test of the deterministic assembly + engine-join helper ------

func Test_assembleSdpReview_FourRows_Deterministic(t *testing.T) {
	id := ProjectID(uuid.NewString())
	wf := pdNewWorkflows()
	proj := sdpReadyProject(projectstate.ProjectID(id))

	review, err := wf.assembleSdpReview(proj, "")
	if err != nil {
		t.Fatalf("assembleSdpReview: %v", err)
	}
	if len(review.Options) != 4 {
		t.Fatalf("want 4 option rows, got %d", len(review.Options))
	}
	if review.Recommendation == "" {
		t.Fatalf("want a non-empty recommendation")
	}
	if !optionInReview(review, review.Recommendation) {
		t.Fatalf("recommendation %s is not one of the assembled options", review.Recommendation)
	}
	for _, r := range review.Options {
		if r.BuildCost.Currency != "USD" {
			t.Fatalf("row %s: want USD build cost, got %q", r.OptionID, r.BuildCost.Currency)
		}
		if r.RevenueSharePercent != 10 {
			t.Fatalf("row %s: want 10%% revenue share, got %v", r.OptionID, r.RevenueSharePercent)
		}
	}

	again, err := wf.assembleSdpReview(proj, "")
	if err != nil {
		t.Fatalf("assembleSdpReview (2nd): %v", err)
	}
	if again.Recommendation != review.Recommendation {
		t.Fatalf("non-deterministic recommendation: %s vs %s", again.Recommendation, review.Recommendation)
	}
	for i := range review.Options {
		if again.Options[i] != review.Options[i] {
			t.Fatalf("non-deterministic row %d: %+v vs %+v", i, again.Options[i], review.Options[i])
		}
	}
}

