// pdEpisodeMgr builds a projectDesignManager exercising ONLY the episode facet
// read ops (Task 9): every other dep stays nil since those ops touch only
// episodes.
func pdEpisodeMgr(eps episode.EpisodeAccess) *projectDesignManager {
	return newProjectDesignManager(nil, nil, nil, nil, nil, nil, nil, nil, nil, eps, nil)
}

// pdSampleEpisodeRecord returns a fully-populated ledger record (every optional
// field set) so the view mapping can be checked field-by-field.
func pdSampleEpisodeRecord(id, targetRef string) episode.EpisodeRecord {
	started := time.Date(2026, 8, 1, 12, 0, 0, 0, time.UTC)
	ended := started.Add(90 * time.Second)
	workerClass := "senior-developer"
	model := "claude-sonnet-5"
	costUSD := 0.42
	numTurns := int64(7)
	gapReason := "the run reported a gap episode"
	tracePath := ".aiarch/state/episodes/traces/" + id + ".jsonl"
	streamed := episode.EpisodeUsage{In: 100, Out: 50, CacheRead: 10, CacheCreate: 5}
	return episode.EpisodeRecord{
		EpisodeID: id,
		Kind:      episode.EpisodeKindDesign,
		TargetRef: targetRef,
		Lineage: &episode.EpisodeLineage{
			WorkflowID: "wf-1",
			RunID:      "run-1",
			ActivityID: strPtr("C-XYZ"),
		},
		WorkerClass:    &workerClass,
		Model:          &model,
		Usage:          episode.EpisodeUsage{In: 1000, Out: 500, CacheRead: 100, CacheCreate: 50},
		StreamedUsage:  &streamed,
		CostUSD:        &costUSD,
		NumTurns:       &numTurns,
		ToolCallCounts: map[string]int64{"Read": 3, "Edit": 2},
		SubagentSpans: []episode.SubagentSpan{
			{ToolUseID: "toolu_1", StartedAt: timePtr(started.Add(time.Second)), EndedAt: timePtr(started.Add(2 * time.Second))},
		},
		StartedAt: started,
		EndedAt:   ended,
		Outcome:   episode.EpisodeGap,
		GapReason: &gapReason,
		TracePath: &tracePath,
	}
}

// pdAssertSampleEpisodeRecordView asserts got is pdSampleEpisodeRecord(id, targetRef)
// mapped field-for-field onto this contract's own EpisodeRecordView. Split into
// three helpers (identity/usage/outcome) purely to keep each under the gocyclo
// budget — together they are one assertion.
func pdAssertSampleEpisodeRecordView(t *testing.T, got EpisodeRecordView, id, targetRef string) {
	t.Helper()
	pdAssertSampleEpisodeRecordIdentity(t, got, id, targetRef)
	assertSampleEpisodeRecordUsage(t, got)
	assertSampleEpisodeRecordOutcome(t, got, id)
}

func pdAssertSampleEpisodeRecordIdentity(t *testing.T, got EpisodeRecordView, id, targetRef string) {
	t.Helper()
	if got.EpisodeID != id {
		t.Fatalf("EpisodeID = %q, want %q", got.EpisodeID, id)
	}
	if got.Kind != EpisodeKindDesign {
		t.Fatalf("Kind = %v, want EpisodeKindDesign", got.Kind)
	}
	if got.TargetRef != targetRef {
		t.Fatalf("TargetRef = %q, want %q", got.TargetRef, targetRef)
	}
	if got.Lineage == nil || got.Lineage.WorkflowID != "wf-1" || got.Lineage.RunID != "run-1" || got.Lineage.ActivityID == nil || *got.Lineage.ActivityID != "C-XYZ" {
		t.Fatalf("Lineage = %+v, want {wf-1 run-1 C-XYZ}", got.Lineage)
	}
	if got.WorkerClass == nil || *got.WorkerClass != "senior-developer" {
		t.Fatalf("WorkerClass = %v", got.WorkerClass)
	}
	if got.Model == nil || *got.Model != "claude-sonnet-5" {
		t.Fatalf("Model = %v", got.Model)
	}
}

// ---- ListEpisodesForArtifact -------------------------------------------------
//
// artifactKind is typed as the contract's own ArtifactKind enum (review fix,
// F1): the ledger's TargetRef is the PascalCase artifactKindString(kind) form
// (episodeRecordFromSummary/captureEpisode, coauthorphase2artifact.go) — NOT
// the camelCase WireName the SPA holds. Taking a bare string here would let a
// caller pass the wire name straight through and silently match nothing.

func Test_PD_ListEpisodesForArtifact_MapsRecordsWithTargetRef(t *testing.T) {
	targetRef := artifactKindString(KindActivityList)
	eps := &fakeEpisodes{listRecords: []episode.EpisodeRecord{
		pdSampleEpisodeRecord("ep-1", targetRef),
	}}
	m := pdEpisodeMgr(eps)

	got, err := m.ListEpisodesForArtifact(fwmanager.Context{Context: context.Background()}, ProjectID("proj-1"), KindActivityList)
	if err != nil {
		t.Fatalf("ListEpisodesForArtifact: unexpected error: %v", err)
	}
	if eps.lastQuery.ProjectID != episode.ProjectID("proj-1") {
		t.Fatalf("ListEpisodes query ProjectID = %q, want proj-1", eps.lastQuery.ProjectID)
	}
	if eps.lastQuery.TargetRef == nil || *eps.lastQuery.TargetRef != targetRef {
		t.Fatalf("ListEpisodes query TargetRef = %v, want *%q (the write path's PascalCase form, not the wire name)", eps.lastQuery.TargetRef, targetRef)
	}
	if targetRef != "ActivityList" {
		t.Fatalf("sanity: artifactKindString(KindActivityList) = %q, want the PascalCase %q", targetRef, "ActivityList")
	}
	if len(got) != 1 {
		t.Fatalf("ListEpisodesForArtifact: got %d records, want 1", len(got))
	}
	pdAssertSampleEpisodeRecordView(t, got[0], "ep-1", targetRef)
}

// Test_PD_ListEpisodesForArtifact_RoundTripsWritePathTargetRefForm proves the read
// side's TargetRef form matches the REAL write path's, not just a test fixture's
// assumption: it builds the ledger record through the actual write-path helper
// (episodeRecordFromSummary, the same one captureEpisode calls in
