// Stage 4a: ONE copy now serves the projectDesign+construction rails (byte-identical
// twins, collapsed by the package merge — arch.CheckFileLayout allows one impl file and one test file).
func boolPtr(b bool) *bool { return &b }

func TestMaterializeActivityPlanProducesTheReaderShape(t *testing.T) {
	sys := projectstate.System{Components: []projectstate.Component{
		{ID: "order-manager", Name: "OrderManager", Kind: projectstate.CompManager},
		{ID: "order-access", Name: "OrderAccess", Kind: projectstate.CompResourceAccess},
	}}
	list, deps, _, err := MaterializeActivityPlan(sys, estimation.ActivityListDeltas{})
	if err != nil {
		t.Fatalf("MaterializeActivityPlan: %v", err)
	}
	if len(list.Activities) == 0 {
		t.Fatal("materialized an empty activity list for a populated System")
	}
	var sawManager bool
	for _, a := range list.Activities {
		if a.Name == "C-order-manager" && a.ComponentID == "order-manager" {
			sawManager = true
		}
	}
	if !sawManager {
		t.Error("materialized list missing C-order-manager")
	}
	if len(deps) == 0 {
		t.Error("materialized no dependency rows")
	}
}

// archivedEmptyActivityListDraft is the EXACT slot-9 document a freshly drafted project
// committed on a real benchmark run (archistrator-bench run-20260815T190639Z-6d9224bb,
// todomvc): the drafting agent authored a deltas document, the wire model
// (projectstate.ActivityList) has nowhere to put deltas, and what survived the codec was
// an activity list with no activities. Every downstream reader then found nothing — the
// SDP assembly died with "option network has zero activities" and the construction pump
// had nothing to dispatch. Kept as a literal so the regression is pinned to the observed
// bytes, not to a re-derivation of what they might have been.
const archivedEmptyActivityListDraft = `{"activities": null}`

func decodeArchivedEmptyActivityList(t *testing.T) *projectstate.ActivityList {
	t.Helper()
	var al projectstate.ActivityList
	if err := json.Unmarshal([]byte(archivedEmptyActivityListDraft), &al); err != nil {
		t.Fatalf("decode the archived slot-9 document: %v", err)
	}
	if len(al.Activities) != 0 {
		t.Fatal("the archived slot-9 document is supposed to decode to ZERO activities - the test would be vacuous")
	}
	return &al
}

// THE REGRESSION. A Phase-2 activity-list draft round must stage the plan DERIVED from the
// committed System, not the document the agent committed on the branch — that is what
// `the-method-activity-list` means by "the server applies the deltas onto the derived
// baseline and stages the result". Before materializePhase2Draft was wired into
// finishDraftRound this staged the archived empty list verbatim (MaterializeActivityPlan
// had no production caller at all), which is exactly how a fresh project reached the SDP
// review with zero activities.
//
// The System is the repo's own committed slot 5 (live state, same convention as
// TestDerivedPlanMatchesCommittedState) so the derivation runs against a real
// architecture rather than a two-component toy.
func Test_CoAuthor_ActivityListDraft_StagesTheDerivedPlan_NotTheAgentsEmptyList(t *testing.T) {
	sys := loadCommittedStateForTest(t)

	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()

	id := ProjectID(uuid.NewString())
	proj := projectstate.Project{ID: projectstate.ProjectID(id), Phase: projectstate.PhaseProjectDesign, Version: 2}
	proj.SystemDesign = pdCommittedSlot(&sys)
	proj.ActivityList = readBackSlot(decodeArchivedEmptyActivityList(t))

	ps := &pdFakeProjectState{project: proj}
	pipe := pdNewFakePipeline()
	wf := pdNewWorkflows()
	pdRegisterCoAuthor(env, wf, ps, pipe)

	env.RegisterDelayedCallback(func() {
		if view := pdSessionView(t, env); view.Stage != ProjectStageAwaitingReview {
			t.Fatalf("want StageAwaitingReview, got %d", view.Stage)
		}
		env.SignalWorkflow(pdSignalReviewDecision, pdReviewDecisionSignal{Decision: ReviewWithdraw})
	}, 30*time.Second)

	env.ExecuteWorkflow(pdExecutionKindCoAuthor, pdCoAuthorInput{ProjectID: id, ArtifactKind: KindActivityList})

	if !env.IsWorkflowCompleted() {
		t.Fatal("workflow did not complete")
	}
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	if len(ps.staged) != 1 {
		t.Fatalf("want 1 staged model, got %d", len(ps.staged))
	}
	staged, ok := ps.staged[0].(*projectstate.ActivityList)
	if !ok {
		t.Fatalf("staged model is not *projectstate.ActivityList: %T", ps.staged[0])
	}
	if len(staged.Activities) == 0 {
		t.Fatal("the staged activity list is EMPTY - the agent's document was staged verbatim instead of the plan derived from the committed System")
	}

	// Not merely non-empty: it must be the SAME plan MaterializeActivityPlan renders, so
	// the drift gate over slot 9 and this write path can never disagree.
	want, _, _, err := MaterializeActivityPlan(sys, estimation.ActivityListDeltas{})
	if err != nil {
		t.Fatalf("MaterializeActivityPlan: %v", err)
	}
	if !reflect.DeepEqual(staged.Activities, want.Activities) {
		t.Errorf("staged %d activities, the derivation renders %d - the staged plan is not the derived plan",
			len(staged.Activities), len(want.Activities))
	}
}

// Every OTHER Phase-2 kind must pass through the materialization seam byte-identical —
// only the activity list derives. Asserted on the planning-assumptions round because that
// is the kind the existing happy-path test drafts.
func TestMaterializePhase2DraftIsInertForEveryOtherKind(t *testing.T) {
	proj := projectstate.Project{}
	pa := &projectstate.PlanningAssumptions{Resources: []string{"alice"}, CalendarDaysPerWeek: 5}
	got, err := materializePhase2Draft(proj, projectstate.KindPlanningAssumptions, pa)
	if err != nil {
		t.Fatalf("materializePhase2Draft: %v", err)
	}
	if got != projectstate.ArtifactModel(pa) {
		t.Errorf("a non-activity-list draft must pass through unchanged, got %#v", got)
	}
}

// A System that derives ZERO construction activities must FAIL LOUDLY rather than stage a
// plan with nothing in it. Staging it would reproduce the very defect this seam exists to
// prevent — the empty plan would just surface one phase later, at the SDP review, with
// nothing pointing back here.
//
// The derivation itself is no longer silent on this input: an empty System still derives
// the three design-prefix activities (a project before its architecture is committed still
// owes the work that produces it), so the guard reads the COMPONENT count. What must not
// happen is a Phase-2 plan staged against an architecture that says nothing.
func TestMaterializePhase2DraftRefusesToStageAnEmptyDerivedPlan(t *testing.T) {
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&projectstate.System{})

	_, err := materializePhase2Draft(proj, projectstate.KindActivityList, decodeArchivedEmptyActivityList(t))
	if err == nil {
		t.Fatal("a System deriving zero construction activities must be an error, not a silently staged empty plan")
	}
	if !strings.Contains(err.Error(), "ZERO construction activities") {
		t.Errorf("the error must say what went wrong, got %q", err.Error())
	}
}

// An uncommitted systemDesign is a precondition failure, not a nil-deref and not an empty
// plan: the whole derivation reads slot 5, so there is nothing to derive from.
func TestMaterializePhase2DraftRequiresACommittedSystem(t *testing.T) {
	_, err := materializePhase2Draft(projectstate.Project{}, projectstate.KindActivityList, decodeArchivedEmptyActivityList(t))
	if err == nil {
		t.Fatal("materializing against an uncommitted systemDesign must be an error")
	}
	if !strings.Contains(err.Error(), "systemDesign") {
		t.Errorf("the error must name the missing prerequisite, got %q", err.Error())
	}
}

// authoredNetworkDraftForTest is what a drafting agent might commit for slot 10: a
// dependency graph and critical path that bear no relation to the derivation, the four
// derived milestones carrying authored display names / public flags but WRONG fan-in, and
// one milestone the derivation does not produce. Every structural byte of it must be
// replaced by the materializer; only the milestone Name/Public survive.
func authoredNetworkDraftForTest() *projectstate.Network {
	return &projectstate.Network{
		Dependencies: []projectstate.NetworkDependency{{Activity: "C-agent-typed", DependsOn: []string{"C-also-agent-typed"}}},
		CriticalPath: []string{"C-agent-typed"},
		Milestones: []projectstate.NetworkMilestone{
			{ID: "M0", Name: "Authored Zero", Public: true, DependsOn: []string{"C-agent-typed"}},
			{ID: "M1", Name: "Authored One", Public: false},
			{ID: "M2", Name: "Authored Two", Public: true},
			{ID: "M3", Name: "Authored Three", Public: false, DependsOn: []string{"C-agent-typed"}},
			{ID: "MX", Name: "Not Derived", Public: true},
		},
	}
}

// zeroFloatActivitySet is the test's INDEPENDENT statement of what slot 10's criticalPath
// is for a derived network: the alphabetically-sorted set of activities ComputeNetwork
// solves on the critical path (projectstate.Network.CriticalPath's documented contract).
func zeroFloatActivitySet(t *testing.T, list projectstate.ActivityList, deps []projectstate.NetworkDependency, ms []projectstate.NetworkMilestone) []string {
	t.Helper()
	acts := estimation.ActivityList{}
	for _, a := range list.Activities {
		acts.Activities = append(acts.Activities, estimation.ActivityItem{Name: a.Name, EffortDays: a.EffortDays})
	}
	nw := estimation.Network{}
	for _, d := range deps {
		nw.Dependencies = append(nw.Dependencies, estimation.NetworkDependency{Activity: d.Activity, DependsOn: d.DependsOn})
	}
	for _, m := range ms {
		nw.Milestones = append(nw.Milestones, estimation.NetworkMilestone{Id: m.ID, DependsOn: m.DependsOn})
	}
	sol, err := estimation.NewEstimationEngine().ComputeNetwork(fweng.Context{}, acts, nw)
	if err != nil {
		t.Fatalf("ComputeNetwork over the derived network: %v", err)
	}
	var cp []string
	for id, n := range sol.Nodes {
		if n.OnCriticalPath {
			cp = append(cp, id)
		}
	}
	sort.Strings(cp)
	return cp
}

// THE SLOT-10 REGRESSION. materializePhase2Draft used to derive the whole plan and then
// throw the dependencies and milestones away (`list, _, _, err :=`), so a Network draft
// passed through byte-identical and slot 10 was whatever the drafting agent typed. A real
// first run must stage the DERIVED network: derived dependencies, derived milestone
// structure (the authored Name/Public kept — they have no derivation source), and a
// criticalPath recomputed by ComputeNetwork over that derived graph.
func TestMaterializePhase2DraftStagesTheDerivedNetwork(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	got, err := materializePhase2Draft(proj, projectstate.KindNetwork, authoredNetworkDraftForTest())
	if err != nil {
		t.Fatalf("materializePhase2Draft(KindNetwork): %v", err)
	}
	staged, ok := got.(*projectstate.Network)
	if !ok {
		t.Fatalf("staged model is not *projectstate.Network: %T", got)
	}

	list, wantDeps, wantMilestones, err := MaterializeActivityPlan(sys, estimation.ActivityListDeltas{})
	if err != nil {
		t.Fatalf("MaterializeActivityPlan: %v", err)
	}

	if !reflect.DeepEqual(staged.Dependencies, wantDeps) {
		t.Errorf("staged %d dependency rows, the derivation renders %d - the agent's dependencies were staged instead of the derived ones",
			len(staged.Dependencies), len(wantDeps))
	}
	if !reflect.DeepEqual(milestonesByIDPS(staged.Milestones), milestonesByIDPS(wantMilestones)) {
		t.Errorf("staged milestone structure %v, the derivation renders %v",
			milestonesByIDPS(staged.Milestones), milestonesByIDPS(wantMilestones))
	}

	wantCP := zeroFloatActivitySet(t, list, wantDeps, wantMilestones)
	if len(wantCP) == 0 {
		t.Fatal("the derived network solves to an EMPTY critical path - the test would be vacuous")
	}
	if !reflect.DeepEqual(staged.CriticalPath, wantCP) {
		t.Errorf("staged criticalPath %v, ComputeNetwork over the derived network gives %v", staged.CriticalPath, wantCP)
	}
	if staged.Computed != nil || staged.Summary != nil {
		t.Error("the compute-at-read block must never be staged - it is absent on disk by contract")
	}
}

// The milestone Name and Public are AUTHORED decorations (see toProjectStateMilestones):
// the derivation has no opinion on them, so the materializer must carry each one across
// from the draft by id — while the milestone SET and fan-in come only from the derivation
// (M0 stays without predecessors; a milestone the derivation does not produce is dropped).
func TestMaterializePhase2DraftKeepsAuthoredMilestoneNameAndPublic(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	got, err := materializePhase2Draft(proj, projectstate.KindNetwork, authoredNetworkDraftForTest())
	if err != nil {
		t.Fatalf("materializePhase2Draft(KindNetwork): %v", err)
	}
	staged, ok := got.(*projectstate.Network)
	if !ok {
		t.Fatalf("staged model is not *projectstate.Network: %T", got)
	}

	type decoration struct {
		name   string
		public bool
	}
	want := map[string]decoration{
		"M0": {"Authored Zero", true},
		"M1": {"Authored One", false},
		"M2": {"Authored Two", true},
		"M3": {"Authored Three", false},
	}
	gotByID := map[string]projectstate.NetworkMilestone{}
	for _, m := range staged.Milestones {
		gotByID[m.ID] = m
	}
	for id, w := range want {
		m, ok := gotByID[id]
		if !ok {
			t.Errorf("derived milestone %q is missing from the staged network", id)
			continue
		}
		if m.Name != w.name || m.Public != w.public {
			t.Errorf("milestone %q: staged name/public %q/%v, the draft authored %q/%v", id, m.Name, m.Public, w.name, w.public)
		}
	}
	if _, ok := gotByID["MX"]; ok {
		t.Error("milestone MX is not produced by the derivation and must not be staged")
	}
	// The fan-in is the DERIVATION's, never the draft's: the agent authored M0 dependsOn
	// [C-agent-typed] and the derivation says [projectDesign] — the design prefix's third
	// activity, which the SDP review ends.
	if m0 := gotByID["M0"]; !reflect.DeepEqual(m0.DependsOn, []string{"projectDesign"}) {
		t.Errorf("M0 dependsOn = %v, want the derived [projectDesign], not the draft's own fan-in", m0.DependsOn)
	}
}

// authoredNetworkDraftMissingMilestoneNameForTest is what a drafting agent commits when it
// omits — or typo's the id of — one derived milestone's authored decoration: M2 carries no
// decoration at all, so materializeNetwork would otherwise commit it with an empty Name.
// NetworkMilestone.Name had no non-emptiness check anywhere (I1, 2026-09-12); the founder
// ruled (2026-08-13) that non-emptiness is enforced in Go code, not by a schema minLength.
func authoredNetworkDraftMissingMilestoneNameForTest() *projectstate.Network {
	return &projectstate.Network{
		Dependencies: []projectstate.NetworkDependency{{Activity: "C-agent-typed", DependsOn: []string{"C-also-agent-typed"}}},
		CriticalPath: []string{"C-agent-typed"},
		Milestones: []projectstate.NetworkMilestone{
			{ID: "M0", Name: "Authored Zero", Public: true, DependsOn: []string{"C-agent-typed"}},
			{ID: "M1", Name: "Authored One", Public: false},
			// M2 omitted — the agent forgot it, or typo'd its id.
			{ID: "M3", Name: "Authored Three", Public: false, DependsOn: []string{"C-agent-typed"}},
		},
	}
}

// A derived milestone with no matching authored decoration (or an authored decoration whose
// Name is blank) must FAIL LOUDLY, never commit an anonymous milestone.
func TestMaterializePhase2DraftRefusesAnonymousMilestone(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	_, err := materializePhase2Draft(proj, projectstate.KindNetwork, authoredNetworkDraftMissingMilestoneNameForTest())
	if err == nil {
		t.Fatal("a derived milestone with no authored Name must be an error, not a silently anonymous milestone")
	}
	if !strings.Contains(err.Error(), "M2") {
		t.Errorf("the error must name the anonymous milestone (M2), got %q", err.Error())
	}
}

// The other half of the refusal above: the draft DOES carry a decoration for the derived
// milestone, but its Name is blank or whitespace-only. A present-but-blank Name is just as
// anonymous as an omitted one, so it must be refused with the same kind (ContractMisuse —
// a malformed draft at the façade boundary), naming the milestone.
func TestMaterializePhase2DraftRefusesAPresentButBlankMilestoneName(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	for _, blank := range []string{"", "   ", "\t \n"} {
		t.Run(strconv.Quote(blank), func(t *testing.T) {
			draft := authoredNetworkDraftForTest()
			for i := range draft.Milestones {
				if draft.Milestones[i].ID == "M2" {
					draft.Milestones[i].Name = blank
				}
			}
			_, err := materializePhase2Draft(proj, projectstate.KindNetwork, draft)
			if err == nil {
				t.Fatalf("milestone M2 is present in the draft with Name %q; it must be refused, not committed anonymous", blank)
			}
			if got := asProjectDesignError(t, err).Kind; got != fwmanager.ContractMisuse {
				t.Errorf("want ContractMisuse, got %d", got)
			}
			if !strings.Contains(err.Error(), "M2") {
				t.Errorf("the error must name the anonymous milestone (M2), got %q", err.Error())
			}
		})
	}
}

// The guard above judges the TRIMMED name, so the stored Name is the trimmed name too: padding
// the guard just called meaningless must not be committed around an authored Name.
func TestMaterializePhase2DraftStoresTheTrimmedMilestoneName(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	draft := authoredNetworkDraftForTest()
	for i := range draft.Milestones {
		if draft.Milestones[i].ID == "M2" {
			draft.Milestones[i].Name = " \tAuthored Two \n"
		}
	}
	got, err := materializePhase2Draft(proj, projectstate.KindNetwork, draft)
	if err != nil {
		t.Fatalf("a padded but non-blank Name must materialize, got %v", err)
	}
	staged, ok := got.(*projectstate.Network)
	if !ok {
		t.Fatalf("staged model is not *projectstate.Network: %T", got)
	}
	for _, m := range staged.Milestones {
		if m.ID == "M2" {
			if m.Name != "Authored Two" {
				t.Fatalf("milestone M2 stored Name %q, want the trimmed %q", m.Name, "Authored Two")
			}
			return
		}
	}
	t.Fatal("derived milestone M2 is missing from the staged network")
}

// The sibling of the refusal above: a draft that authors every derived milestone's Name still
// materializes cleanly, with no milestone left with an empty Name.
func TestMaterializePhase2DraftMaterializesAFullyNamedDraft(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)

	got, err := materializePhase2Draft(proj, projectstate.KindNetwork, authoredNetworkDraftForTest())
	if err != nil {
		t.Fatalf("a fully-named draft must materialize cleanly, got %v", err)
	}
	staged, ok := got.(*projectstate.Network)
	if !ok {
		t.Fatalf("staged model is not *projectstate.Network: %T", got)
	}
	if len(staged.Milestones) == 0 {
		t.Fatal("the derivation must still produce milestones - the test would be vacuous")
	}
	for _, m := range staged.Milestones {
		if strings.TrimSpace(m.Name) == "" {
			t.Errorf("milestone %q materialized with an empty Name", m.ID)
		}
	}
}

// The network derives from slot 5 exactly as the activity list does, so it carries the
// same precondition, and a draft of the wrong model type is a loud error, not a panic.
func TestMaterializePhase2DraftNetworkPreconditions(t *testing.T) {
	if _, err := materializePhase2Draft(projectstate.Project{}, projectstate.KindNetwork, authoredNetworkDraftForTest()); err == nil ||
		!strings.Contains(err.Error(), "systemDesign") {
		t.Errorf("a network draft against an uncommitted systemDesign must fail naming it, got %v", err)
	}

	sys := loadCommittedStateForTest(t)
	proj := projectstate.Project{}
	proj.SystemDesign = pdCommittedSlot(&sys)
	if _, err := materializePhase2Draft(proj, projectstate.KindNetwork, &projectstate.ActivityList{}); err == nil {
		t.Error("a KindNetwork draft carrying a non-Network model must be an error")
	}
}

// loadCommittedStateForTest reads the repo's own committed project document and returns
// its slot-5 System. It reads LIVE state rather than a fixture on purpose: the derivation
// is asserted against the real architecture, which a synthetic fixture cannot reproduce.
//
// It no longer decodes core use cases (Task 10a): the founder's ruling drops I-*
// integration activities entirely, which were the only thing that ever read them, and
// MaterializeActivityPlan no longer takes a use-case-id parameter to feed. It no longer
// returns the .activityExecution keys either (2026-09-12): those were the legacy
// short-name rows the deleted alias table joined onto the derived ids, and the founder's
// D9 ruling removed both.
//
// The path is resolved relative to this test file's package directory
// (server/internal/manager/projectdesign), so it does not depend on the caller's cwd.
func loadCommittedStateForTest(t *testing.T) projectstate.System {
	t.Helper()
	raw, err := os.ReadFile(committedStatePath)
	if err != nil {
		t.Fatalf("read committed project state at %s: %v", committedStatePath, err)
	}
	var doc struct {
		Slots map[string]struct {
			Model json.RawMessage `json:"model"`
		} `json:"slots"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode committed project state: %v", err)
	}

	var sys projectstate.System
	if err := json.Unmarshal(doc.Slots["5"].Model, &sys); err != nil {
		t.Fatalf("decode slot 5 (System): %v", err)
	}
	if len(sys.Components) == 0 {
		t.Fatal("slot 5 decoded to zero components - the test would be vacuous")
	}
	return sys
}

// A delta document that violates the vocabulary must fail the READ, loudly. A silently
// dropped bad delta is the zombie failure mode returning by another door.
func TestMaterializeActivityPlanPropagatesDeltaErrors(t *testing.T) {
	sys := projectstate.System{Components: []projectstate.Component{
		{ID: "order-manager", Name: "OrderManager", Kind: projectstate.CompManager},
	}}
	_, _, _, err := MaterializeActivityPlan(sys, estimation.ActivityListDeltas{
		Overrides: []estimation.ActivityOverride{{Activity: "C-gone", Justification: "j"}},
	})
	if err == nil {
		t.Fatal("a delta naming an underived activity must fail the read")
	}
}

// TestFixtureSystemViewMatchesLiveCommittedSystem is the standing guard against the exact
// defect class that produced the Task 10b blocker: the estimation package's frozen golden
// parity fixture (testdata/system_view.json) asserting a constructionProfile/
// provisioning/uiSurface value that the LIVE committed System (slot 5) does not actually
// carry. Task 7 checked agreement once with a one-off script; nothing re-ran it when Task
// 10a changed the fixture to stamp "provided" on four utilities, so slot 5 silently fell
// out of step and the golden-parity test kept asserting 40 against a fixture that no
// longer described the real architecture. This makes that re-check standing rather than
// one-off, reading LIVE state on purpose (same convention as loadCommittedStateForTest).
func TestFixtureSystemViewMatchesLiveCommittedSystem(t *testing.T) {
	sys := loadCommittedStateForTest(t)
	live := toEstimationSystemView(sys)
	liveByID := make(map[string]estimation.SystemComponent, len(live.Components))
	for _, c := range live.Components {
		liveByID[c.ID] = c
	}

	const rel = "../../engine/estimation/testdata/system_view.json"
	raw, err := os.ReadFile(rel)
	if err != nil {
		t.Fatalf("read fixture at %s: %v", rel, err)
	}
	var fixture estimation.SystemView
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("decode fixture: %v", err)
	}
	if len(fixture.Components) == 0 {
		t.Fatal("fixture decoded to zero components - the test would be vacuous")
	}

	for _, f := range fixture.Components {
		l, ok := liveByID[f.ID]
		if !ok {
			t.Errorf("fixture component %q has no live committed-System counterpart (slot 5)", f.ID)
			continue
		}
		if l.Kind != f.Kind {
			t.Errorf("component %q: fixture kind %q, live committed System kind %q", f.ID, f.Kind, l.Kind)
		}
		if l.ConstructionProfile != f.ConstructionProfile {
			t.Errorf("component %q: fixture constructionProfile %q, live committed System constructionProfile %q — the fixture has drifted from the committed System", f.ID, f.ConstructionProfile, l.ConstructionProfile)
		}
		if l.Provisioning != f.Provisioning {
			t.Errorf("component %q: fixture provisioning %q, live committed System provisioning %q — the fixture has drifted from the committed System", f.ID, f.Provisioning, l.Provisioning)
		}
		if l.UiSurface != f.UiSurface {
			t.Errorf("component %q: fixture uiSurface %v, live committed System uiSurface %v — the fixture has drifted from the committed System", f.ID, f.UiSurface, l.UiSurface)
		}
		// buildStatus joins the comparison because it is now the field that decides
		// whether a component derives any construction activity AT ALL: a "planned"
		// component has no code to build, so the derivation skips it. Fixture drift on
		// this one field silently changes the size of the plan, not just a label.
		if l.BuildStatus != f.BuildStatus {
			t.Errorf("component %q: fixture buildStatus %q, live committed System buildStatus %q — the fixture has drifted from the committed System", f.ID, f.BuildStatus, l.BuildStatus)
		}
	}

	// I1 (2026-08-10): relationships were never compared here, so the 74-relationship
	// fixture could diverge from the live committed System's relationships silently —
	// exactly the defect class this test exists to catch, just on the OTHER field. Edges
	// are compared as a sorted "from->to" multiset so ordering differences between the
	// fixture and the live document never cause a false failure.
	edgeStrings := func(rels []estimation.SystemRelationship) []string {
		out := make([]string, 0, len(rels))
		for _, r := range rels {
			out = append(out, r.From+"->"+r.To)
		}
		sort.Strings(out)
		return out
	}
	fixtureEdges := edgeStrings(fixture.Relationships)
	liveEdges := edgeStrings(live.Relationships)
	if !reflect.DeepEqual(fixtureEdges, liveEdges) {
		t.Errorf("fixture relationships (%d) do not match live committed System relationships (%d, slot 5) — the fixture has drifted from the committed System", len(fixtureEdges), len(liveEdges))
	}
}

// loadDerivedPlanCheckFixtures reads the repo's own committed project document (LIVE
// state, same convention as loadCommittedStateForTest) and returns the slot-5 System,
// the top-level activityListOverrides member (Task 10b Step 3's authored-overrides
// sidecar — gone since founder F3, 2026-09-12, deleted all 25 overrides; the member is an
// empty residue, still decoded so a re-authored override would be caught), the committed
// slot-9 ActivityList,
// and the committed slot-10 Network (I1, 2026-08-10: the gate must cover dependencies
// and milestones too, not just the activity list — a slot-5 RELATIONSHIP edit reshapes
// slot 10 without touching slot 9 at all, and nothing was re-deriving or comparing that).
func loadDerivedPlanCheckFixtures(t *testing.T) (projectstate.System, estimation.ActivityListDeltas, projectstate.ActivityList, projectstate.Network) {
	t.Helper()
	const rel = "../../../../.aiarch/state/project.json"
	raw, err := os.ReadFile(rel)
	if err != nil {
		t.Fatalf("read committed project state at %s: %v", rel, err)
	}
	var doc struct {
		Slots map[string]struct {
			Model json.RawMessage `json:"model"`
		} `json:"slots"`
		ActivityListOverrides estimation.ActivityListDeltas `json:"activityListOverrides"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode committed project state: %v", err)
	}

	var sys projectstate.System
	if err := json.Unmarshal(doc.Slots["5"].Model, &sys); err != nil {
		t.Fatalf("decode slot 5 (System): %v", err)
	}
	if len(sys.Components) == 0 {
		t.Fatal("slot 5 decoded to zero components - the test would be vacuous")
	}

	var committed projectstate.ActivityList
	if err := json.Unmarshal(doc.Slots["9"].Model, &committed); err != nil {
		t.Fatalf("decode slot 9 (ActivityList): %v", err)
	}
	if len(committed.Activities) == 0 {
		t.Fatal("slot 9 decoded to zero activities - the test would be vacuous")
	}

	var committedNetwork projectstate.Network
	if err := json.Unmarshal(doc.Slots["10"].Model, &committedNetwork); err != nil {
		t.Fatalf("decode slot 10 (Network): %v", err)
	}
	if len(committedNetwork.Dependencies) == 0 {
		t.Fatal("slot 10 decoded to zero dependencies - the test would be vacuous")
	}

	return sys, doc.ActivityListOverrides, committed, committedNetwork
}

// depsByActivityPS indexes a []projectstate.NetworkDependency by activity name, with
// each DependsOn set sorted so the comparison in TestDerivedPlanMatchesCommittedState is
// order-independent.
func depsByActivityPS(deps []projectstate.NetworkDependency) map[string][]string {
	out := make(map[string][]string, len(deps))
	for _, d := range deps {
		preds := append([]string(nil), d.DependsOn...)
		sort.Strings(preds)
		out[d.Activity] = preds
	}
	return out
}

// milestonesByIDPS indexes a []projectstate.NetworkMilestone by id, with each DependsOn
// set sorted, same convention as depsByActivityPS.
func milestonesByIDPS(ms []projectstate.NetworkMilestone) map[string][]string {
	out := make(map[string][]string, len(ms))
	for _, m := range ms {
		preds := append([]string(nil), m.DependsOn...)
		sort.Strings(preds)
		out[m.ID] = preds
	}
	return out
}

// TestDerivedPlanMatchesCommittedState is the Task 10b drift gate (`make
// derived-plan-check`): it re-derives the Phase-2 plan from the committed System (slot 5)
// (the overrides sidecar it also decodes is empty since founder F3, 2026-09-12), and
// fails if the result differs from what slot 9
// and slot 10 hold. This is what makes ACT-COMPONENT-COVERAGE deletable (Task 11, retired
// 2026-08-09) — re-deriving and comparing is strictly stronger than checking coverage —
// and it is backed by a real Go test specifically so it also runs in the normal suite; a
// drift gate nobody remembers to run by hand is no gate at all.
//
// I1 (2026-08-10): dependencies and milestones are compared alongside activities. Before
// this, the gate discarded MaterializeActivityPlan's deps return with `_` entirely, so a
// slot-5 RELATIONSHIP edit — which reshapes slot 10 without adding/removing/resizing a
// single activity — re-derived nothing and was caught by nothing.
func TestDerivedPlanMatchesCommittedState(t *testing.T) {
	sys, deltas, committed, committedNetwork := loadDerivedPlanCheckFixtures(t)

	got, gotDeps, gotMilestones, err := MaterializeActivityPlan(sys, deltas)
	if err != nil {
		t.Fatalf("MaterializeActivityPlan over the committed System + overrides: %v", err)
	}

	assertDerivedActivitiesMatch(t, got.Activities, committed.Activities)
	assertDerivedDependenciesMatch(t, gotDeps, committedNetwork.Dependencies)
	assertDerivedMilestonesMatch(t, gotMilestones, committedNetwork.Milestones)
	assertCommittedNetworkIsMaterialized(t, got, gotDeps, gotMilestones, committedNetwork)
}

// assertCommittedNetworkIsMaterialized is the WHOLE-slot-10 half of the gate (2026-09-12).
// The structural halves above compare dependency rows and milestone fan-in as sets, which
// leaves criticalPath — and the rest of the document — unguarded. This runs the SAME
// materializeNetwork the co-author staging seam runs over the re-derived plan (with the
// committed milestone Name/Public as the authored decorations) and requires the committed
// slot 10 to be exactly that document. Any drift in criticalPath, ordering, or a stray
// authored field fails here.
func assertCommittedNetworkIsMaterialized(
	t *testing.T,
	got projectstate.ActivityList,
	gotDeps []projectstate.NetworkDependency,
	gotMilestones []projectstate.NetworkMilestone,
	committedNetwork projectstate.Network,
) {
	t.Helper()
	want, err := materializeNetwork(got, gotDeps, gotMilestones, committedNetwork)
	if err != nil {
		t.Fatalf("materializeNetwork over the re-derived plan: %v", err)
	}
	if !reflect.DeepEqual(want.CriticalPath, committedNetwork.CriticalPath) {
		t.Errorf("slot 10 criticalPath has drifted: ComputeNetwork over the derived network gives %v, committed slot 10 holds %v",
			want.CriticalPath, committedNetwork.CriticalPath)
	}
	if !reflect.DeepEqual(want, committedNetwork) {
		wantJSON, _ := json.Marshal(want)
		gotJSON, _ := json.Marshal(committedNetwork)
		t.Errorf("committed slot 10 is not the materialized network:\n materialized: %s\n committed:    %s", wantJSON, gotJSON)
	}
}

// ---------------------------------------------------------------------------
// The committed-state WRITERS: `make derived-plan-write` and `make construction-state-reset`.
// ---------------------------------------------------------------------------
//
// .aiarch/state/project.json is compiler input (it drives the Go contract layer, the
// OpenAPI document, the TS client and Temporal), and it is never hand-edited. These two
// writers are the committed, reproducible way to change the parts of it that no live store
// verb covers: re-materializing the derived plan, and resetting construction state onto
// it. They are env-gated tests, not cmd/ tools, because network materialization has no
// exported path. MaterializeActivityPlan is exported, but it returns only the activity
// list, dependency rows and milestones; the committed slot 10 (criticalPath and the rest
// of the document) is materialized by materializePhase2Draft / materializeNetwork, the
// Manager's own staging seam, which is unexported. This package can call it; a cmd/ tool
// cannot.
//
// Both go through the projectstate codec: the document is decoded with DecodeProjectJSON,
// edited as a typed Project and re-encoded with EncodeProjectJSON. Only the members whose
// codec encoding the edit actually changed are spliced back into the original bytes, and
// only when the document's bytes for that member are its codec encoding (spliceMember).
// The codec carries neither updatedAt nor the activityListOverrides sidecar through a
// round trip, so a whole-document rewrite would silently drop both. Each writer names the
// members it may change, and changing any other fails the write.

// committedStatePath is the repo's own project.json, relative to this package directory.
const committedStatePath = "../../../../.aiarch/state/project.json"

// TestWriteDerivedPlan is `make derived-plan-write`, the WRITE half of derived-plan-check.
// It re-materializes slots 9 and 10 of the committed project.json from the committed
// System through materializePhase2Draft — the function a real first run stages through —
// so TestDerivedPlanMatchesCommittedState passes by construction afterwards. Skipped
// unless DERIVED_PLAN_WRITE=1, so the ordinary suite never rewrites committed state.
func TestWriteDerivedPlan(t *testing.T) {
	if os.Getenv("DERIVED_PLAN_WRITE") != "1" {
		t.Skip("set DERIVED_PLAN_WRITE=1 (make derived-plan-write) to rewrite slots 9 and 10 of the committed project.json")
	}
	changed, err := rewriteStateFile(committedStatePath, derivedPlanMembers(), writeDerivedPlan)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("derived-plan-write changed %d member(s): %v", len(changed), changed)
}

// TestResetConstructionState is `make construction-state-reset`: resetConstructionState
// applied to the committed project.json. Skipped unless CONSTRUCTION_STATE_RESET=1 — it
// deletes construction history, so it runs only when asked for by name.
func TestResetConstructionState(t *testing.T) {
	if os.Getenv("CONSTRUCTION_STATE_RESET") != "1" {
		t.Skip("set CONSTRUCTION_STATE_RESET=1 (make construction-state-reset) to reset construction state in the committed project.json")
	}
	changed, err := rewriteStateFile(committedStatePath, resetMembers(), resetConstructionState)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("construction-state-reset changed %d member(s): %v", len(changed), changed)
}

// writeDerivedPlan sets slots 9 and 10 to what materializePhase2Draft stages from the
// committed System. When either model changes, every committed plan dependent is flagged
// stale, caused by the first changed slot — their numbers were computed over the plan this
// replaces. Revisions are not bumped: this re-materializes what the System already
// implies, it is not a reviewed amendment.
func writeDerivedPlan(p *projectstate.Project) error {
	list, err := materializePhase2Draft(*p, projectstate.KindActivityList, p.ActivityList.Model)
	if err != nil {
		return err
	}
	net, err := materializePhase2Draft(*p, projectstate.KindNetwork, p.Network.Model)
	if err != nil {
		return err
	}
	listSame, err := projectstate.SameArtifactModel(p.ActivityList.Model, list)
	if err != nil {
		return err
	}
	netSame, err := projectstate.SameArtifactModel(p.Network.Model, net)
	if err != nil {
		return err
	}
	p.ActivityList.Model = list
	p.Network.Model = net
	switch {
	case !listSame:
		return flagPlanDependentsStale(p, projectstate.KindActivityList)
	case !netSame:
		return flagPlanDependentsStale(p, projectstate.KindNetwork)
	}
	return nil
}

// resetConstructionState is the founder's D9 reset (2026-09-12: "i essentially want no
// legacy rows/activities ... just delete the old stuff"), applied once the plan is
// materialized from Table 11-1:
//   - .activityExecution is emptied. Every row was keyed by a legacy short id, and none
//     of the rows that carried history names an activity the derived plan holds. A first
//     real run holds no row until the pump starts an activity; the codec omits an empty
//     map, so the member disappears rather than becoming {}.
//   - Every committed plan dependent (the four solution options, the risk model, the SDP
//     review) is flagged stale, caused by the activity list: their numbers were computed
//     over the 40-activity network the derivation replaced. Phase 2 is NOT re-run here;
//     the flag is the non-blocking signal that it must be.
//   - .constructionProgress is recomputed from the now-empty record: nothing is earned and
//     no week of tracking has elapsed, so Week is 0 and the earned-value series is empty —
//     every recorded point was an observation over the legacy rows. The framing that is
//     not a function of construction records (TotalWeeks, HandOffModel, SupervisionCap) is
//     carried; TotalWeeks' own basis is the SDP option flagged stale alongside it. The EV
//     curve itself is computed at read (computeEVAtRead), from the same empty record.
func resetConstructionState(p *projectstate.Project) error {
	p.ActivityExecution = nil
	if cp := p.ConstructionProgress; cp != nil {
		recomputed := *cp
		recomputed.Week = 0
		recomputed.Points = nil
		p.ConstructionProgress = &recomputed
	}
	return flagPlanDependentsStale(p, projectstate.KindActivityList)
}

// flagPlanDependentsStale flags every committed plan dependent StaleBasis, caused by
// upstream at its current revision — the same flag and cause shape commitTransition sets
// on the downstream slots of a re-commit.
func flagPlanDependentsStale(p *projectstate.Project, upstream projectstate.ArtifactKind) error {
	cause := &projectstate.StaleCause{UpstreamKind: upstream.WireName(), UpstreamRevision: pdSlotFor(*p, upstream).Revisions}
	for _, kind := range planDependentKinds() {
		slot, ok := planDependentSlots[kind]
		if !ok {
			return fmt.Errorf("no slot accessor for plan dependent %s", kind.WireName())
		}
		if s := slot(p); s.Status == projectstate.ReviewCommitted {
			s.StaleBasis = true
			s.StaleBasisCause = cause
		}
	}
	return nil
}

// planDependentKinds is every Phase-2 kind downstream of the network: the four solution
// options, the risk model and the SDP review. It is read off Phase2RequiredKinds so the
// Phase-2 spine has one source of order.
func planDependentKinds() []projectstate.ArtifactKind {
	kinds := projectstate.Phase2RequiredKinds()
	for i, k := range kinds {
		if k == projectstate.KindNetwork {
			return kinds[i+1:]
		}
	}
	return nil
}

// planDependentSlots addresses each plan dependent's slot for writing (pdSlotFor only reads).
var planDependentSlots = map[projectstate.ArtifactKind]func(*projectstate.Project) *projectstate.ArtifactSlot{
	projectstate.KindNormalSolution:       func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.NormalSolution },
	projectstate.KindDecompressedSolution: func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.DecompressedSolution },
	projectstate.KindSubcriticalSolution:  func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.SubcriticalSolution },
	projectstate.KindCompressedSolution:   func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.CompressedSolution },
	projectstate.KindRiskModel:            func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.RiskModel },
	projectstate.KindSdpReview:            func(p *projectstate.Project) *projectstate.ArtifactSlot { return &p.SdpReview },
}

// slotMember is the member path of kind's slot in the document ("slots/<ordinal>").
func slotMember(kind projectstate.ArtifactKind) string {
	return "slots/" + strconv.Itoa(int(kind))
}

// withPlanDependents adds every plan dependent's slot to members.
func withPlanDependents(members ...string) map[string]bool {
	allowed := make(map[string]bool, len(members)+len(planDependentSlots))
	for _, m := range members {
		allowed[m] = true
	}
	for _, kind := range planDependentKinds() {
		allowed[slotMember(kind)] = true
	}
	return allowed
}

// derivedPlanMembers is what writeDerivedPlan may change: slots 9 and 10, and the plan
// dependents it flags stale when either one moves.
func derivedPlanMembers() map[string]bool {
	return withPlanDependents(slotMember(projectstate.KindActivityList), slotMember(projectstate.KindNetwork))
}

// resetMembers is what resetConstructionState may change.
func resetMembers() map[string]bool {
	return withPlanDependents("activityExecution", "constructionProgress")
}

// rewriteStateFile applies edit to the project document at path and writes back only the
// members the edit changed, returning their paths ("activityExecution", "slots/11",
// …). allowed names the members the edit may change; any other change fails the write.
// Nothing is written when nothing changed.
func rewriteStateFile(path string, allowed map[string]bool, edit func(*projectstate.Project) error) ([]string, error) {
	raw, err := os.ReadFile(path) //nolint:gosec // the writer reads the document it was pointed at.
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	out, changed, err := rewriteState(raw, edit)
	if err != nil {
		return nil, err
	}
	for _, member := range changed {
		if !allowed[member] {
			return nil, fmt.Errorf("the edit changed %s, which this writer may not touch (allowed: %v) — refusing to write", member, allowed)
		}
	}
	if len(changed) == 0 {
		return nil, nil
	}
	if err := os.WriteFile(path, out, 0o600); err != nil {
		return nil, fmt.Errorf("write %s: %w", path, err)
	}
	return changed, nil
}

// rewriteState is rewriteStateFile over bytes: it returns the rewritten document and the
// members it rewrote.
func rewriteState(raw []byte, edit func(*projectstate.Project) error) ([]byte, []string, error) {
	body, trailer, err := compactState(raw)
	if err != nil {
		return nil, nil, err
	}
	proj, err := decodeState(raw)
	if err != nil {
		return nil, nil, err
	}
	before, err := encodeCompact(proj)
	if err != nil {
		return nil, nil, err
	}
	// What the codec writes must survive its OWN round trip: encode, decode and encode
	// again has to give the same bytes. A member that is a fixed point cannot mean
	// anything other than what the document already meant — so a byte difference between
	// the document and the codec's encoding of that member is the codec NORMALIZING a
	// legacy form into the current one, not a rewrite that changes the datum. That is the
	// second half of "this rewrite is safe"; the first is spliceMember's loss check
	// (nothing the codec does not carry is dropped). One half no decoded comparison can
	// see, one half no structural comparison can see. Checked PER MEMBER, not over the
	// document: members no writer may touch (serviceContracts' raw $defs, slots 4-6)
	// legitimately re-order under the codec, and they must not veto a slot rewrite.
	reproj, err := decodeState(before)
	if err != nil {
		return nil, nil, fmt.Errorf("re-decode the codec's own encoding: %w", err)
	}
	stable, err := encodeCompact(reproj)
	if err != nil {
		return nil, nil, err
	}
	if err := edit(&proj); err != nil {
		return nil, nil, err
	}
	after, err := encodeCompact(proj)
	if err != nil {
		return nil, nil, err
	}
	spliced, changed, err := spliceMembers(body, before, stable, after, "")
	if err != nil {
		return nil, nil, err
	}
	if err := confirmSplice(spliced, after); err != nil {
		return nil, nil, err
	}
	var out bytes.Buffer
	if err := json.Indent(&out, spliced, "", "  "); err != nil {
		return nil, nil, fmt.Errorf("indent the rewritten document: %w", err)
	}
	out.Write(trailer)
	return out.Bytes(), changed, nil
}

// compactState returns the document compacted, plus the whitespace after its closing
// brace. It refuses a document that re-indenting would not reproduce byte-for-byte:
// writing one would smuggle a reformat of unrelated state into the diff.
func compactState(raw []byte) ([]byte, []byte, error) {
	trimmed := bytes.TrimRight(raw, " \t\r\n")
	trailer := raw[len(trimmed):]
	var body bytes.Buffer
	if err := json.Compact(&body, trimmed); err != nil {
		return nil, nil, fmt.Errorf("parse the project document: %w", err)
	}
	var again bytes.Buffer
	if err := json.Indent(&again, body.Bytes(), "", "  "); err != nil {
		return nil, nil, fmt.Errorf("indent the project document: %w", err)
	}
	if !bytes.Equal(again.Bytes(), trimmed) {
		return nil, nil, errors.New("re-indenting the project document does not reproduce it byte-for-byte; a rewrite would reformat unrelated state — refusing")
	}
	return body.Bytes(), trailer, nil
}

// decodeState decodes a project document through the projectstate codec, under the id
// the document itself carries.
func decodeState(raw []byte) (projectstate.Project, error) {
	var head struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(raw, &head); err != nil {
		return projectstate.Project{}, fmt.Errorf("read the project id: %w", err)
	}
	proj, ok, err := projectstate.DecodeProjectJSON(raw, projectstate.ProjectID(head.ID))
	if err != nil {
		return projectstate.Project{}, err
	}
	if !ok {
		return projectstate.Project{}, errors.New("the file holds no project document")
	}
	return proj, nil
}

// encodeCompact encodes p through the projectstate codec, compacted.
func encodeCompact(p projectstate.Project) ([]byte, error) {
	enc, err := projectstate.EncodeProjectJSON(p)
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	if err := json.Compact(&out, enc); err != nil {
		return nil, fmt.Errorf("compact the encoded project: %w", err)
	}
	return out.Bytes(), nil
}

// confirmSplice proves the spliced document is the codec's: decoding it and re-encoding
// must give exactly what the codec encoded from the edited Project. Whatever the codec
// does not carry (updatedAt's value, the overrides sidecar) is outside both sides.
func confirmSplice(spliced, after []byte) error {
	proj, err := decodeState(spliced)
	if err != nil {
		return err
	}
	again, err := encodeCompact(proj)
	if err != nil {
		return err
	}
	if !bytes.Equal(again, after) {
		return errors.New("the spliced document does not decode to the edited project — refusing to write")
	}
	return nil
}

// stateMember is one member of a JSON object, in document order.
type stateMember struct {
	key   string
	value json.RawMessage
}

// spliceMembers rebuilds the compact object raw member by member, in raw's order. A member
// whose codec encoding is the same before and after the edit keeps raw's bytes; one that
// differs takes the after encoding, or is dropped when after omits it. Slots are compared
// one level down, so an edit to one slot rewrites that slot alone. It returns the path of
// every member it rewrote.
func spliceMembers(raw, before, stable, after []byte, path string) ([]byte, []string, error) {
	members, err := objectMembers(raw)
	if err != nil {
		return nil, nil, err
	}
	was, err := memberValues(before)
	if err != nil {
		return nil, nil, err
	}
	fixed, err := memberValues(stable)
	if err != nil {
		return nil, nil, err
	}
	now, err := memberValues(after)
	if err != nil {
		return nil, nil, err
	}
	if added := addedMember(members, was, now); added != "" {
		return nil, nil, fmt.Errorf("the edit adds %s, which the document does not hold; this writer rewrites members in place and cannot place a new one", memberPath(path, added))
	}
	out := make([]stateMember, 0, len(members))
	var changed []string
	for _, m := range members {
		kept, rewritten, err := spliceMember(m, was[m.key], fixed[m.key], now[m.key], memberPath(path, m.key))
		if err != nil {
			return nil, nil, err
		}
		out = append(out, kept...)
		changed = append(changed, rewritten...)
	}
	return joinMembers(out), changed, nil
}

// spliceMember resolves one member for spliceMembers: kept holds zero or one member.
//
// A member the edit changes is replaced by its codec encoding, so the codec must carry
// ALL of it. Otherwise replacing it silently drops whatever the codec does not carry (an
// unknown field, a value it cannot represent), and confirmSplice cannot see the loss —
// it compares codec output with codec output. The committed document holds such members
// today (slots 4-6, serviceContracts, testingState); no writer may change them.
//
// "The codec carries all of it" is asked of projectstate.CodecCarriesEveryMember, which
// names every member the encoding would DROP. It used to be asked as byte identity —
// the member's document bytes had to BE its codec encoding — and that was the wrong
// question, which is the defect this fixes (ruling 2026-09-22, found by the stage-2
// slot-5 amendment). The codec NORMALIZES on decode: slots 9 and 10 of this repo's own
// document carry a staleAck comment written before Status was derived and before the
// Reopened/Replies members existed, so decoding rewrites "addressed" to "answered" and
// fills the two members. Nothing is lost — but the bytes differ, so byte identity
// refused, and NO derived-plan rewrite could land at all while the committed document
// held a legacy form. Refusing the codec's own documented normalizer is not safety; the
// normalized bytes landing in the splice IS the upgrade, and it is what we want.
//
// The complementary half — that what the codec writes decodes back to the same Project,
// so a rewrite cannot change what the document MEANS — is asserted once per rewrite over
// the whole document in rewriteState.
func spliceMember(m stateMember, was, fixed, now json.RawMessage, path string) (kept []stateMember, changed []string, err error) {
	switch {
	case bytes.Equal(was, now):
		return []stateMember{m}, nil, nil
	case now == nil:
		return nil, []string{path}, nil
	case path == "slots":
		value, changed, err := spliceMembers(m.value, was, fixed, now, path)
		if err != nil {
			return nil, nil, err
		}
		return []stateMember{{key: m.key, value: value}}, changed, nil
	}
	if !bytes.Equal(m.value, was) {
		lost, lerr := projectstate.CodecCarriesEveryMember(m.value, was)
		if lerr != nil {
			return nil, nil, fmt.Errorf("compare %s with its codec encoding: %w", path, lerr)
		}
		if len(lost) > 0 {
			return nil, nil, fmt.Errorf("the edit changes %s, and the codec does not carry %v; rewriting it would silently drop them — refusing", path, lost)
		}
		if !bytes.Equal(was, fixed) {
			return nil, nil, fmt.Errorf("the edit changes %s, and the codec's encoding of it does not survive its own round trip; the rewrite would not be stable — refusing", path)
		}
	}
	return []stateMember{{key: m.key, value: now}}, []string{path}, nil
}

// addedMember names a member the edit introduced that raw does not hold, or "".
func addedMember(members []stateMember, was, now map[string]json.RawMessage) string {
	held := make(map[string]bool, len(members))
	for _, m := range members {
		held[m.key] = true
	}
	keys := make([]string, 0, len(now))
	for k := range now {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		if !held[k] && !bytes.Equal(was[k], now[k]) {
			return k
		}
	}
	return ""
}

// objectMembers decodes a compact JSON object into its members, in document order.
func objectMembers(raw []byte) ([]stateMember, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	if _, err := dec.Token(); err != nil {
		return nil, fmt.Errorf("read object: %w", err)
	}
	var out []stateMember
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			return nil, fmt.Errorf("read member key: %w", err)
		}
		key, _ := tok.(string)
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, fmt.Errorf("read member %q: %w", key, err)
		}
		out = append(out, stateMember{key: key, value: value})
	}
	return out, nil
}

// memberValues indexes a compact JSON object's members by key; an absent object is empty.
func memberValues(raw []byte) (map[string]json.RawMessage, error) {
	if len(raw) == 0 {
		return map[string]json.RawMessage{}, nil
	}
	members, err := objectMembers(raw)
	if err != nil {
		return nil, err
	}
	out := make(map[string]json.RawMessage, len(members))
	for _, m := range members {
		out[m.key] = m.value
	}
	return out, nil
}

// joinMembers re-emits members as a compact JSON object.
func joinMembers(members []stateMember) []byte {
	var b bytes.Buffer
	b.WriteByte('{')
	for i, m := range members {
		if i > 0 {
			b.WriteByte(',')
		}
		key, _ := json.Marshal(m.key) // a string always marshals
		b.Write(key)
		b.WriteByte(':')
		b.Write(m.value)
	}
	b.WriteByte('}')
	return b.Bytes()
}

// memberPath joins a member key onto its parent path.
func memberPath(parent, key string) string {
	if parent == "" {
		return key
	}
	return parent + "/" + key
}

// stateFixture encodes p through the projectstate codec, then adds what a committed
// document carries that the codec does not — a real updatedAt and the
// activityListOverrides sidecar — so a test can prove a rewrite leaves both alone.
func stateFixture(t *testing.T, p projectstate.Project) []byte {
	t.Helper()
	enc, err := projectstate.EncodeProjectJSON(p)
	if err != nil {
		t.Fatalf("encode fixture: %v", err)
	}
	const zeroStamp = `"updatedAt": "0001-01-01T00:00:00Z"`
	if !bytes.Contains(enc, []byte(zeroStamp)) {
		t.Fatalf("fixture encoding carries no %s to replace", zeroStamp)
	}
	withSidecar := bytes.Replace(enc, []byte(zeroStamp),
		[]byte(`"activityListOverrides": {"overrides": []}, "updatedAt": "2026-08-09T05:30:44.213963Z"`), 1)
	var compact, out bytes.Buffer
	if err := json.Compact(&compact, withSidecar); err != nil {
		t.Fatalf("compact fixture: %v", err)
	}
	if err := json.Indent(&out, compact.Bytes(), "", "  "); err != nil {
		t.Fatalf("indent fixture: %v", err)
	}
	out.WriteByte('\n')
	return out.Bytes()
}

// constructionResetFixture holds a legacy construction row, a finished-looking progress
// record, a committed plan dependent (normal solution) and an UNcommitted one (SDP review).
func constructionResetFixture(t *testing.T) projectstate.Project {
	t.Helper()
	model := func(kind projectstate.ArtifactKind) projectstate.ArtifactModel {
		m, ok := projectstate.NewModelForKind(kind)
		if !ok {
			t.Fatalf("no model for %s", kind.WireName())
		}
		return m
	}
	p := projectstate.Project{ID: "fixture", Phase: projectstate.PhaseProjectDesign, Version: 7}
	p.ActivityList = projectstate.ArtifactSlot{Status: projectstate.ReviewCommitted, Model: model(projectstate.KindActivityList), Revisions: 3}
	p.NormalSolution = projectstate.ArtifactSlot{Status: projectstate.ReviewCommitted, Model: model(projectstate.KindNormalSolution), Revisions: 1}
	p.SdpReview = readBackSlot(model(projectstate.KindSdpReview))
	p.ActivityExecution = map[string]projectstate.ActivityExecution{"C-BM": {ActivityID: "C-BM"}}
	p.ConstructionProgress = &projectstate.ConstructionProgress{
		Week: 49, TotalWeeks: 49, HandOffModel: "Senior hand-off", SupervisionCap: 3,
		Points: []projectstate.EvPoint{{Week: 49, EarnedPct: 100, PlannedPct: 100, Note: "legacy"}},
	}
	return p
}

// writeFixtureFile writes raw to a fresh project.json and returns its path.
func writeFixtureFile(t *testing.T, raw []byte) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "project.json")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatalf("write fixture: %v", err)
	}
	return path
}

// The reset rewrites exactly its three kinds of member — the construction record, the
// progress record and each COMMITTED plan dependent — and leaves every other byte alone,
// including the two members the codec cannot carry.
func TestResetConstructionStateRewritesOnlyItsMembers(t *testing.T) {
	raw := stateFixture(t, constructionResetFixture(t))
	path := writeFixtureFile(t, raw)

	changed, err := rewriteStateFile(path, resetMembers(), resetConstructionState)
	if err != nil {
		t.Fatalf("rewriteStateFile: %v", err)
	}
	want := []string{"activityExecution", "constructionProgress", slotMember(projectstate.KindNormalSolution)}
	sort.Strings(changed)
	if !reflect.DeepEqual(changed, want) {
		t.Errorf("changed members = %v, want %v", changed, want)
	}

	got, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read back: %v", err)
	}
	for _, keep := range []string{`"updatedAt": "2026-08-09T05:30:44.213963Z"`, `"activityListOverrides": {`, `"overrides": []`} {
		if !bytes.Contains(got, []byte(keep)) {
			t.Errorf("the rewrite lost %s", keep)
		}
	}
	if bytes.Contains(got, []byte(`"activityExecution"`)) {
		t.Error("an empty construction record must be omitted, the codec's shape for 'no rows'")
	}
	proj, err := decodeState(got)
	if err != nil {
		t.Fatalf("decode the rewritten document: %v", err)
	}
	assertResetStaleness(t, proj)
	assertResetProgress(t, proj.ConstructionProgress)
}

func assertResetStaleness(t *testing.T, proj projectstate.Project) {
	t.Helper()
	wantCause := projectstate.StaleCause{UpstreamKind: "activityList", UpstreamRevision: 3}
	if !proj.NormalSolution.StaleBasis || proj.NormalSolution.StaleBasisCause == nil || *proj.NormalSolution.StaleBasisCause != wantCause {
		t.Errorf("committed normal solution: staleBasis=%v cause=%v, want true %v",
			proj.NormalSolution.StaleBasis, proj.NormalSolution.StaleBasisCause, wantCause)
	}
	if proj.SdpReview.StaleBasis {
		t.Error("an uncommitted plan dependent must not be flagged stale — the same rule commitTransition applies")
	}
	if proj.ActivityList.StaleBasis {
		t.Error("the activity list is the cause, not a dependent")
	}
}

func assertResetProgress(t *testing.T, cp *projectstate.ConstructionProgress) {
	t.Helper()
	if cp == nil {
		t.Fatal("the progress record must be recomputed, not deleted")
	}
	want := projectstate.ConstructionProgress{Week: 0, TotalWeeks: 49, HandOffModel: "Senior hand-off", SupervisionCap: 3}
	if !reflect.DeepEqual(*cp, want) {
		t.Errorf("recomputed progress = %+v, want %+v", *cp, want)
	}
}

// A change to a member the writer does not own fails the write and leaves the file alone.
func TestRewriteStateFileRefusesAMemberOutsideItsAllowedSet(t *testing.T) {
	raw := stateFixture(t, constructionResetFixture(t))
	path := writeFixtureFile(t, raw)

	allowed := map[string]bool{"constructionProgress": true, slotMember(projectstate.KindNormalSolution): true}
	_, err := rewriteStateFile(path, allowed, resetConstructionState)
	if err == nil || !strings.Contains(err.Error(), "activityExecution") {
		t.Fatalf("want a refusal naming activityExecution, got %v", err)
	}
	got, _ := os.ReadFile(path)
	if !bytes.Equal(got, raw) {
		t.Error("a refused write must leave the file byte-for-byte")
	}
}

// An edit that changes nothing writes nothing.
func TestRewriteStateFileLeavesAnUnchangedDocumentAlone(t *testing.T) {
	raw := stateFixture(t, constructionResetFixture(t))
	path := writeFixtureFile(t, raw)

	changed, err := rewriteStateFile(path, nil, func(*projectstate.Project) error { return nil })
	if err != nil || len(changed) != 0 {
		t.Fatalf("a no-op edit: changed=%v err=%v", changed, err)
	}
	got, _ := os.ReadFile(path)
	if !bytes.Equal(got, raw) {
		t.Error("a no-op edit must leave the file byte-for-byte")
	}
}

// reindentFixture re-emits a fixture document with the given indent and a trailing newline.
func reindentFixture(t *testing.T, raw []byte, indent string) []byte {
	t.Helper()
	var compact, out bytes.Buffer
	if err := json.Compact(&compact, raw); err != nil {
		t.Fatalf("compact fixture: %v", err)
	}
	if err := json.Indent(&out, compact.Bytes(), "", indent); err != nil {
		t.Fatalf("indent fixture: %v", err)
	}
	out.WriteByte('\n')
	return out.Bytes()
}

// assertRefusedUntouched runs a rewrite that must be refused with an error containing
// want, and proves the file is left byte-for-byte.
func assertRefusedUntouched(t *testing.T, raw []byte, allowed map[string]bool, edit func(*projectstate.Project) error, want string) {
	t.Helper()
	path := writeFixtureFile(t, raw)
	changed, err := rewriteStateFile(path, allowed, edit)
	if err == nil || !strings.Contains(err.Error(), want) {
		t.Fatalf("want a refusal containing %q, got changed=%v err=%v", want, changed, err)
	}
	got, _ := os.ReadFile(path)
	if !bytes.Equal(got, raw) {
		t.Error("a refused write must leave the file byte-for-byte")
	}
}

// A member the edit changes is replaced by its codec encoding, so a field the codec does
// not carry would vanish from it without a trace — confirmSplice compares codec output
// with codec output and cannot see the loss. Slot 11 is a member the reset may change;
// an unknown field in it must stop the write, not be dropped.
//
// This is the case that survives the 2026-09-22 ruling: the guard stopped asking for byte
// identity (which also refused the codec's own normalizer) and started asking what the
// codec DROPS — so a genuinely foreign byte change is still refused, and now the refusal
// names the member that would be lost.
func TestRewriteStateFileRefusesToRewriteAMemberTheCodecDoesNotCarry(t *testing.T) {
	var buf bytes.Buffer
	if err := json.Compact(&buf, stateFixture(t, constructionResetFixture(t))); err != nil {
		t.Fatalf("compact fixture: %v", err)
	}
	compact := buf.Bytes()
	slot := slotMember(projectstate.KindNormalSolution)
	key := []byte(`"` + strings.TrimPrefix(slot, "slots/") + `":{`)
	if !bytes.Contains(compact, key) {
		t.Fatalf("fixture has no %s to plant the unknown field in", key)
	}
	planted := bytes.Replace(compact, key, append(append([]byte{}, key...), []byte(`"extraUnknown":1,`)...), 1)
	raw := reindentFixture(t, planted, "  ")

	assertRefusedUntouched(t, raw, resetMembers(), resetConstructionState,
		"the edit changes "+slot+", and the codec does not carry [extraUnknown]")
}

// A document that is not in the canonical two-space indent is refused rather than
// silently reformatted: writing it would smuggle a whole-file reformat into the diff.
func TestRewriteStateFileRefusesADocumentNotInCanonicalIndent(t *testing.T) {
	raw := reindentFixture(t, stateFixture(t, constructionResetFixture(t)), "    ")
	assertRefusedUntouched(t, raw, resetMembers(), resetConstructionState, "does not reproduce it byte-for-byte")
}

// This writer rewrites members in place; it cannot place a member the document does not
// already hold, so an edit that introduces one is refused by name.
func TestRewriteStateFileRefusesAnEditThatAddsAMember(t *testing.T) {
	p := constructionResetFixture(t)
	p.ConstructionProgress = nil
	raw := stateFixture(t, p)
	if bytes.Contains(raw, []byte(`"constructionProgress"`)) {
		t.Fatal("fixture went vacuous: it already holds constructionProgress")
	}
	addProgress := func(p *projectstate.Project) error {
		p.ConstructionProgress = &projectstate.ConstructionProgress{Week: 1, TotalWeeks: 2}
		return nil
	}
	assertRefusedUntouched(t, raw, map[string]bool{"constructionProgress": true}, addProgress, "the edit adds constructionProgress")
}

// confirmSplice is the backstop against a splicer bug: the spliced document must decode
// to exactly the edited project. A correct splicer never reaches the refusal, so it is
// pinned directly — with a positive control, so the test cannot pass by refusing always.
func TestConfirmSpliceRefusesADocumentThatIsNotTheEditedProject(t *testing.T) {
	p := constructionResetFixture(t)
	edited := p
	edited.Version = p.Version + 1
	spliced, err := encodeCompact(p)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	after, err := encodeCompact(edited)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	if err := confirmSplice(after, after); err != nil {
		t.Fatalf("positive control: a splice equal to the edit must be confirmed, got %v", err)
	}
	if err := confirmSplice(spliced, after); err == nil || !strings.Contains(err.Error(), "does not decode to the edited project") {
		t.Fatalf("want a refusal of a splice that is not the edited project, got %v", err)
	}
}

// writeDerivedPlan re-derives slots 9 and 10 and flags the plan dependents only when that
// moves the plan. Over the repo's own committed state the plan is already materialized, so
// nothing is flagged; over a slot 9 that drifted from the System the dependents are
// flagged, caused by the activity list.
func TestWriteDerivedPlanFlagsPlanDependentsOnlyWhenThePlanChanges(t *testing.T) {
	sys, _, committed, committedNetwork := loadDerivedPlanCheckFixtures(t)
	normal, _ := projectstate.NewModelForKind(projectstate.KindNormalSolution)
	project := func(list projectstate.ActivityList) projectstate.Project {
		net := committedNetwork
		p := projectstate.Project{}
		p.SystemDesign = pdCommittedSlot(&sys)
		p.ActivityList = projectstate.ArtifactSlot{Status: projectstate.ReviewCommitted, Model: &list, Revisions: 3}
		p.Network = pdCommittedSlot(&net)
		p.NormalSolution = pdCommittedSlot(normal)
		return p
	}

	current := project(committed)
	if err := writeDerivedPlan(&current); err != nil {
		t.Fatalf("writeDerivedPlan over the committed plan: %v", err)
	}
	if current.NormalSolution.StaleBasis {
		t.Error("re-materializing the plan the System already implies must flag nothing")
	}

	drifted := committed
	drifted.Activities = committed.Activities[1:]
	moved := project(drifted)
	if err := writeDerivedPlan(&moved); err != nil {
		t.Fatalf("writeDerivedPlan over a drifted plan: %v", err)
	}
	if got := moved.ActivityList.Model.(*projectstate.ActivityList); len(got.Activities) != len(committed.Activities) {
		t.Errorf("slot 9 re-derived to %d activities, want %d", len(got.Activities), len(committed.Activities))
	}
	wantCause := projectstate.StaleCause{UpstreamKind: "activityList", UpstreamRevision: 3}
	if !moved.NormalSolution.StaleBasis || moved.NormalSolution.StaleBasisCause == nil || *moved.NormalSolution.StaleBasisCause != wantCause {
		t.Errorf("after a plan change the normal solution must be stale with cause %v, got %v %v",
			wantCause, moved.NormalSolution.StaleBasis, moved.NormalSolution.StaleBasisCause)
	}
}

// assertDerivedActivitiesMatch is the slot-9 half of TestDerivedPlanMatchesCommittedState,
// split out to keep the top-level test under the gocyclo cap.
func assertDerivedActivitiesMatch(t *testing.T, got, committed []projectstate.ActivityItem) {
	t.Helper()
	gotByName := make(map[string]projectstate.ActivityItem, len(got))
	for _, a := range got {
		gotByName[a.Name] = a
	}
	wantByName := make(map[string]projectstate.ActivityItem, len(committed))
	for _, a := range committed {
		wantByName[a.Name] = a
	}

	if len(got) != len(committed) {
		t.Errorf("re-derived %d activities, committed slot 9 holds %d", len(got), len(committed))
	}
	for name, want := range wantByName {
		g, ok := gotByName[name]
		if !ok {
			t.Errorf("committed slot-9 activity %q is no longer produced by the derivation", name)
			continue
		}
		if g.EffortDays != want.EffortDays {
			t.Errorf("activity %q: re-derived effortDays %v, committed slot 9 holds %v", name, g.EffortDays, want.EffortDays)
		}
		if g.RiskBucket != want.RiskBucket {
			t.Errorf("activity %q: re-derived riskBucket %v, committed slot 9 holds %v", name, g.RiskBucket, want.RiskBucket)
		}
		if g.WorkerClass != want.WorkerClass {
			t.Errorf("activity %q: re-derived workerClass %q, committed slot 9 holds %q", name, g.WorkerClass, want.WorkerClass)
		}
		if g.Coding != want.Coding {
			t.Errorf("activity %q: re-derived coding %v, committed slot 9 holds %v", name, g.Coding, want.Coding)
		}
		if g.ComponentID != want.ComponentID {
			t.Errorf("activity %q: re-derived componentId %q, committed slot 9 holds %q", name, g.ComponentID, want.ComponentID)
		}
		if g.Title != want.Title {
			t.Errorf("activity %q: re-derived title %q, committed slot 9 holds %q", name, g.Title, want.Title)
		}
	}
	for name := range gotByName {
		if _, ok := wantByName[name]; !ok {
			t.Errorf("the derivation now produces %q, which committed slot 9 does not hold — slot 9 has drifted from the System", name)
		}
	}
}

// assertDerivedDependenciesMatch is the slot-10-dependencies half of
// TestDerivedPlanMatchesCommittedState (I1, 2026-08-10).
