// ===========================================================================
// B1.2 — THE SESSION VIEW REPORTS THE HUMAN STAGE (plan B1.2).
// ===========================================================================

func b12View(t *testing.T, env *testsuite.TestWorkflowEnvironment) ConstructionSessionView {
	t.Helper()
	enc, err := env.QueryWorkflow(querySessionState)
	if err != nil {
		t.Fatalf("query session state: %v", err)
	}
	var v ConstructionSessionView
	if err := enc.Get(&v); err != nil {
		t.Fatalf("decode session view: %v", err)
	}
	return v
}

func b12Gate(v ConstructionSessionView) string {
	if v.AwaitingGate == nil {
		return ""
	}
	return *v.AwaitingGate
}

func b12Decide(env *testsuite.TestWorkflowEnvironment, key string, d PhaseDecision) func() {
	return func() {
		sig := phaseDecisionSignal{Phase: key, Decision: d}
		if d == PhaseSendBack {
			sig.Feedback = &ReviewFeedback{Notes: "redraft it"}
		}
		env.SignalWorkflow(signalPhaseDecision, sig)
	}
}

// b12SendBack is b12Decide's send-back with the operator's own words, for the tests that
// assert those words landed somewhere durable.
func b12SendBack(env *testsuite.TestWorkflowEnvironment, key, notes string) func() {
	return func() {
		env.SignalWorkflow(signalPhaseDecision, phaseDecisionSignal{
			Phase: key, Decision: PhaseSendBack, Feedback: &ReviewFeedback{Notes: notes},
		})
	}
}

func b12Run(env *testsuite.TestWorkflowEnvironment) {
	env.ExecuteWorkflow(executionKindConstructActivity, constructActivityInput{ProjectID: "p", ActivityID: "C-Orders", Activity: sampleActivity()})
}

// ===========================================================================
// THE EXECUTION LEDGER (stage 3, task 5): the construction child workflow WRITES.
//
// Before this, the run recorded nothing about what it did: attempt numbers were minted
// and thrown away, every roster the review engine computed was discarded once it had been
// displayed, and a send-back left a one-line OperatorNote and nothing else — no roster, no
// verdict, no thread, no round number, no subject. These pin the writes, and the fence
// that keeps an in-flight execution off them.
// ===========================================================================

// ledgerGateEnv is the rig these tests share: the REAL review engine (the roster is the
// thing being persisted, so a fake roster would prove nothing) behind a policy that gates
// detailed design.
func ledgerGateEnv(t *testing.T) (*testsuite.TestWorkflowEnvironment, *csFakeProjectState) {
	t.Helper()
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign))
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	// The pipeline mines an episode on every observation (the local executor's arm), so
	// the attempts these tests read back cite something a reader can actually follow.
	registerConstruct(env, csNewWorkflows(deps), ps, &csFakePipeline{phase: PipelineSucceeded, episode: csCaptureSeamSummary()})
	return env, ps
}

// A send-back must now leave a ROUND, not just a note: the roster the engine computed,
// the verdict that was given, the round number, and the subject it judged.
func Test_Construct_SendBack_PersistsTheReviewRound(t *testing.T) {
	env, ps := ledgerGateEnv(t)
	env.RegisterDelayedCallback(b12SendBack(env, "detailed_design", "split the contract"), 30*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 90*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	gate := projectstate.GateTaskFor(projectstate.MethodPhaseDetailedDesign)
	rounds := roundsOnGate(ps, "C-Orders", gate)
	if len(rounds) != 2 {
		t.Fatalf("a send-back then an approval is TWO rounds on %s; got %d: %+v", gate, len(rounds), rounds)
	}
	assertRejectionRound(t, rounds[0], "split the contract")
	if r2 := rounds[1]; r2.Round != 2 || r2.Outcome != projectstate.RoundPassed || r2.DecidedBy != decidedByOperator {
		t.Fatalf("the redraft opens round 2 and the approval decides it; got %+v", r2)
	}
	// The un-gated phases still leave a round each: an auto-passed gate is a gate that
	// happened, and it is the record a vibes preset otherwise leaves nothing of.
	if auto, ok := roundOnGate(ps, "C-Orders", projectstate.GateTaskFor(projectstate.MethodPhaseRequirements), 1); !ok ||
		auto.Outcome != projectstate.RoundPassed || auto.DecidedBy != decidedByPolicy {
		t.Fatalf("an un-gated phase records the round its policy passed; got %+v ok=%v", auto, ok)
	}
}

// Attempts are written by the RUN now, not reconstructed. The work task and the gate task
// each get one per revision, and the AttemptID format is unchanged so the episode
// ledger's TargetRef join survives.
func Test_Construct_WritesTheAttemptLedger(t *testing.T) {
	env, ps := ledgerGateEnv(t)
	env.RegisterDelayedCallback(b12SendBack(env, "detailed_design", "split the contract"), 30*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 90*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	held := map[string]projectstate.TaskAttempt{}
	for _, a := range ps.execution("C-Orders").Attempts {
		held[a.AttemptID] = a
	}
	// detailedDesign#1 was rejected at designReview#1, so the developer repeated the
	// preceding task: detailedDesign#2, passed at designReview#2 (App A, Figure A-1).
	want := map[string]projectstate.TaskOutcome{
		"C-Orders:detailedDesign:1": projectstate.OutcomePassed,
		"C-Orders:designReview:1":   projectstate.OutcomeRejected,
		"C-Orders:detailedDesign:2": projectstate.OutcomePassed,
		"C-Orders:designReview:2":   projectstate.OutcomePassed,
	}
	for id, outcome := range want {
		a, ok := held[id]
		if !ok {
			t.Fatalf("attempt %s is not in the ledger; got %v", id, slices.Sorted(maps.Keys(held)))
		}
		if a.Outcome != outcome {
			t.Errorf("attempt %s outcome = %q, want %q", id, a.Outcome, outcome)
		}
	}
	// The work attempt cites the episode it burned — the join the SPA follows from an
	// attempt row to what the agent actually did.
	if ev := held["C-Orders:detailedDesign:1"].Evidence; ev.Kind != projectstate.EvidenceEpisode || ev.Ref == "" {
		t.Errorf("a work attempt cites its episode; got %+v", ev)
	}
	// And the activity itself was opened against a pinned lifecycle before any of it.
	row := ps.execution("C-Orders")
	if row.Pin == nil || row.Pin.TypeKey == "" || row.Pin.AssetsVersion == "" {
		t.Fatalf("OpenActivity must pin the lifecycle in force; got %+v", row.Pin)
	}
}

// An old execution keeps its old history: with the marker absent, nothing is written to
// the execution ledger at all — and the retired rail still records what it always did.
func Test_Construct_WithoutTheLedgerFence_WritesNothing(t *testing.T) {
	env, ps := ledgerGateEnv(t)
	// Mocks follow registration (the test environment refuses the other order).
	env.OnGetVersion(changeExecutionLedger, workflow.DefaultVersion, 1).Return(workflow.DefaultVersion)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 30*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	row := ps.execution("C-Orders")
	switch {
	case len(row.Attempts) != 0:
		t.Fatalf("DefaultVersion writes no attempt; got %+v", row.Attempts)
	case len(row.Reviews) != 0:
		t.Fatalf("DefaultVersion opens no round; got %+v", row.Reviews)
	case row.Pin != nil || row.StartedAt != nil:
		t.Fatalf("DefaultVersion never opens the activity; got %+v", row)
	}
	// The old rail is untouched: the phase completion and the exit still land where they
	// always did, which is what makes an in-flight execution safe across the deploy.
	if !ps.phaseCompleted("C-Orders", "detailed_design") {
		t.Error("DefaultVersion must still record the phase completion on the retired rail")
	}
	if len(ps.exited) != 1 || ps.exited[0].outcome != projectstate.ActivityOutcomeCompleted {
		t.Fatalf("DefaultVersion must still record the binary exit; got %+v", ps.exited)
	}
}

// assertRejectionRound pins everything round 1 has to say about the send-back that a
// NoteSendBack could not: the roster, the verdict, the operator's words, the subject and
// the task it judges.
func assertRejectionRound(t *testing.T, r projectstate.ReviewRound, summary string) {
	t.Helper()
	switch {
	case r.Outcome != projectstate.RoundSentBack || r.Round != 1:
		t.Fatalf("round 1 must be a recorded send-back; got outcome=%q round=%d", r.Outcome, r.Round)
	case len(r.Reviewers) == 0:
		t.Fatalf("the round must carry the roster the engine computed; got none")
	case len(r.Verdicts) != 1 || r.Verdicts[0].Verdict != projectstate.VerdictSendBack:
		t.Fatalf("the human's verdict must be a row in Verdicts; got %+v", r.Verdicts)
	case r.Verdicts[0].Summary != summary:
		t.Fatalf("the verdict must carry the operator's own words; got %q", r.Verdicts[0].Summary)
	case r.SubjectRef.Ref == "":
		t.Fatalf("a round must name what it judged (the staged ref); got %+v", r.SubjectRef)
	case r.Reviews != projectstate.AgentTaskFor(projectstate.MethodPhaseDetailedDesign):
		t.Fatalf("a round names the task it judges; got %q", r.Reviews)
	}
}

// roundsOnGate is every round on one gate task, in ledger order.
func roundsOnGate(ps *csFakeProjectState, activityID string, gate projectstate.MethodTask) []projectstate.ReviewRound {
	var out []projectstate.ReviewRound
	for _, r := range ps.execution(activityID).Reviews {
		if r.TaskID == gate {
			out = append(out, r)
		}
	}
	return out
}

// A phase gate names itself and its occurrence; a redraft re-enters as a NEW occurrence;
// the decision clears the awaiting fields.
func Test_SessionView_PhaseGate_ReportsTheOccurrenceAndClearsOnDecision(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign))
	registerConstruct(env, csNewWorkflows(gateDeps(ps)), ps, csNewFakePipeline())
	start := env.Now()
	var atGate, afterRedraft ConstructionSessionView
	env.RegisterDelayedCallback(func() { atGate = b12View(t, env) }, 10*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseSendBack), 30*time.Second)
	env.RegisterDelayedCallback(func() { afterRedraft = b12View(t, env) }, 45*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 60*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	if atGate.Stage != StageAwaitingApproval || b12Gate(atGate) != "detailed_design" {
		t.Fatalf("at the gate: stage=%v gate=%q, want awaitingApproval at detailed_design", atGate.Stage, b12Gate(atGate))
	}
	if atGate.AwaitingSince == nil || !atGate.AwaitingSince.Equal(start) {
		t.Fatalf("awaitingSince = %v, want the gate's entry time %v", atGate.AwaitingSince, start)
	}
	if atGate.AwaitingUntil != nil {
		t.Fatalf("an approval gate has no deadline, got awaitingUntil %v", atGate.AwaitingUntil)
	}
	if atGate.RedraftExhausted || atGate.Attempt != 1 || atGate.AttemptBudget != maxVarianceAttempts {
		t.Fatalf("exhausted=%v attempt=%d/%d, want false, 1/%d", atGate.RedraftExhausted, atGate.Attempt, atGate.AttemptBudget, maxVarianceAttempts)
	}
	if afterRedraft.AwaitingSince == nil || !afterRedraft.AwaitingSince.Equal(start.Add(30*time.Second)) {
		t.Fatalf("after the redraft awaitingSince = %v, want the re-entry time %v (a new occurrence)", afterRedraft.AwaitingSince, start.Add(30*time.Second))
	}
	// The re-entered occurrence is a gate like any other: it carries its reviewer set.
	if afterRedraft.ReviewSet == nil {
		t.Fatalf("after the redraft the gate must still carry its reviewer set, got %+v", afterRedraft.ReviewSet)
	}
	b12AssertGateClosed(t, b12View(t, env))
}

// b12AssertGateClosed asserts that a decided gate left NOTHING of its occurrence on the
// session view: neither the awaiting fields nor — I1 — the reviewer set or the engine's
// refusal to propose one, which belong to the occurrence and not to the activity.
func b12AssertGateClosed(t *testing.T, done ConstructionSessionView) {
	t.Helper()
	if done.AwaitingGate != nil || done.AwaitingSince != nil || done.AwaitingUntil != nil {
		t.Fatalf("the decision must clear the awaiting fields, got gate=%v since=%v until=%v", done.AwaitingGate, done.AwaitingSince, done.AwaitingUntil)
	}
	if done.ReviewSet != nil || done.ReviewSetError != nil {
		t.Fatalf("the decision must clear the reviewer set, got reviewSet=%+v reviewSetError=%v", done.ReviewSet, done.ReviewSetError)
	}
}

// A gated phase must show its reviewer set. The Manager used to pass the phase's wire
// name ("detailed_design") where the engine accepts only its own kind vocabulary
// ("DetailedDesign"), and runPhaseGate dropped the error, so ReviewSet was nil at every
// gate of every activity. The REAL engine is wired here: a fake that accepts any kind is
// how the defect stayed hidden.
func Test_SessionView_PhaseGate_CarriesTheReviewerSet(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign))
	deps := gateDeps(ps)
	deps.Review = review.NewReviewEngine()
	registerConstruct(env, csNewWorkflows(deps), ps, csNewFakePipeline())
	var atGate ConstructionSessionView
	env.RegisterDelayedCallback(func() { atGate = b12View(t, env) }, 10*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 30*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	if atGate.Stage != StageAwaitingApproval || b12Gate(atGate) != "detailed_design" {
		t.Fatalf("not at the detailed_design gate: stage=%v gate=%q", atGate.Stage, b12Gate(atGate))
	}
	if atGate.ReviewSet == nil || len(atGate.ReviewSet.Reviewers) == 0 {
		t.Fatalf("the detailed_design gate shows no reviewers: ReviewSet=%+v", atGate.ReviewSet)
	}
	if r := atGate.ReviewSet.Reviewers[0]; r.Role != "architect" || !r.MayAmend {
		t.Fatalf("a service's detailed design is reviewed by the architect, who may amend; got %+v", r)
	}
}

// The (activity type, lifecycle phase) -> review kind table MOVED into the reviewEngine
// when ProposeReviews took the activity type (spec 2026-09-20 §5.4, stage 2). Its two
// tests — the totality proof over every dispatchable cell and the hand-checkable rows —
// live in internal/engine/review/engine_test.go now
// (Test_ProposeReviews_IsTotalOverEveryTypeAndPhase, Test_ProposeReviews_PerKind).
// What the Manager still owes is below: that it hands the engine the activity's TYPE
// and the phase's wire name, and that it obeys the verdict it gets back.

// The Manager asks the engine ONCE per gate and obeys its RequiresHuman. Under vibes
// the gate does not suspend; with the floor touched at construction it does, whatever
// the preset says; under "full" it suspends at the very first phase. This is the same
// behaviour the retired ReviewPolicy.EffectiveGate gave, now decided in one place —
// the REAL engine is wired here, so a drift in the engine's table fails this test.
func Test_PhaseGate_ObeysTheEnginesRequiresHuman(t *testing.T) {
	for _, c := range []struct {
		name     string
		policy   projectstate.ReviewPolicy
		floor    bool
		suspends bool
	}{
		{"vibes walks through", vibesPreset(), false, false},
		{"vibes stops at a floor-touching construction dispatch", vibesPreset(), true, true},
		{"full stops at the first phase", fullPreset(), false, true},
		{"the legacy empty policy walks through", projectstate.ReviewPolicy{}, false, false},
	} {
		t.Run(c.name, func(t *testing.T) {
			var ts testsuite.WorkflowTestSuite
			env := ts.NewTestWorkflowEnvironment()
			ps := newFakeProjectStateWithPolicy(c.policy)
			if c.floor {
				ps.project.ServiceContracts = map[string]projectstate.ServiceContract{"comp-1": deployTouchingContract()}
			}
			deps := gateDeps(ps)
			deps.Review = review.NewReviewEngine()
			registerConstruct(env, csNewWorkflows(deps), ps, csNewFakePipeline())
			// Deliberately NO signal: a gate that opens can only stay open.
			b12Run(env)
			// The floor guards the CONSTRUCTION dispatch only, so the phases before it
			// still complete; "full" gates from requirements onwards.
			firstGated := "construction"
			if !c.floor {
				firstGated = "requirements"
			}
			if got := ps.phaseCompleted("C-Orders", firstGated); got == c.suspends {
				t.Fatalf("%s: phase %q completed=%v with no approval signal, want completed=%v",
					c.name, firstGated, got, !c.suspends)
			}
		})
	}
}

// The Manager passes the activity's TYPE and the lifecycle phase's wire name — never a
// kind it computed itself — plus the floor flag and the stored policy document.
func Test_PhaseGate_PassesTypeAndPhaseToTheEngine(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign))
	fake := &fakeReview{set: review.ReviewSet{
		Reviewers: []review.Reviewer{{Role: "architect", Perspective: "architecture", ReferenceArtifact: "architecture"}},
	}}
	deps := gateDeps(ps)
	deps.Review = fake
	registerConstruct(env, csNewWorkflows(deps), ps, csNewFakePipeline())
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 30*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	if len(fake.calls) == 0 {
		t.Fatal("the engine was never asked")
	}
	for i, want := range []string{"requirements", "detailed_design", "test_plan", "construction", "integration"} {
		if i >= len(fake.calls) {
			t.Fatalf("the engine was asked %d times, want one call per phase: %+v", len(fake.calls), fake.calls)
		}
		if fake.calls[i].activityType != review.ActivityTypeService || fake.calls[i].lifecyclePhase != want {
			t.Fatalf("call %d: the engine was asked with %+v, want (service, %q)", i, fake.calls[i], want)
		}
		if fake.calls[i].floorTouched {
			t.Errorf("call %d: no contract is committed, so the floor must read false", i)
		}
	}
	// The stored document reaches the engine intact: the legacy gate map, re-keyed.
	if got := fake.calls[0].policy.GatedPhasesByType["service"]; !slices.Equal(got, []string{"detailed_design"}) {
		t.Errorf("the engine got gatedPhasesByType[service] = %v, want the stored document", got)
	}
}

// An engine refusal is LOUD but never costly: it is logged and shown (reviewSetError)
// and the gate OPENS rather than failing the activity or holding it without a roster.
// Failing closed would gate phases that run ungated today — before the engine owned the
// gate verdict a refusal could not reach the decision at all — and stage 2 is not
// allowed to make that behaviour change. No approval signal is registered here: the
// activity must finish on its own.
func Test_SessionView_PhaseGate_ShowsAnEngineRefusalAndOpensTheGate(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign))
	deps := gateDeps(ps)
	fr := &fakeReview{err: errors.New("policy produced an empty reviewer set")}
	deps.Review = fr
	registerConstruct(env, csNewWorkflows(deps), ps, csNewFakePipeline())
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("an engine refusal must not fail the activity: %v", err)
	}
	for _, phase := range []string{"requirements", "detailed_design", "test_plan", "construction", "integration"} {
		if !ps.phaseCompleted("C-Orders", phase) {
			t.Fatalf("a refusal must open the gate, but %s never completed", phase)
		}
	}
	done := b12View(t, env)
	if done.ReviewSetError == nil || !strings.Contains(*done.ReviewSetError, "empty reviewer set") {
		t.Fatalf("reviewSetError = %v, want the engine's reason on the view", done.ReviewSetError)
	}
	if done.ReviewSet != nil {
		t.Fatalf("a refusal leaves no roster, got %+v", done.ReviewSet)
	}
	if len(fr.calls) == 0 || fr.calls[0].activityType != review.ActivityTypeService || fr.calls[0].lifecyclePhase != "requirements" {
		t.Fatalf("the Manager asked with %+v, want the first phase of a service activity", fr.calls)
	}
}

// An escalation waits at "takeover"; its deadline is since+wait when the wait is bounded
// and absent when it waits indefinitely; the operator's Retry starts the next attempt.
func Test_SessionView_Escalation_ReportsTakeoverAndItsDeadline(t *testing.T) {
	for _, c := range []struct {
		name string
		wait time.Duration
	}{{"bounded wait", time.Hour}, {"waits indefinitely", 0}} {
		t.Run(c.name, func(t *testing.T) {
			var ts testsuite.WorkflowTestSuite
			env := ts.NewTestWorkflowEnvironment()
			ps := newFakeProjectStateWithPolicy(projectstate.ReviewPolicy{})
			wf := csNewWorkflows(wfDeps{Intervention: &fakeIntervention{directive: intervention.VarianceEscalate}, Review: &fakeReview{}, EscalationWaitTimeout: c.wait})
			registerConstruct(env, wf, ps, newFakePipelineFailingOnce("detailed_design"))
			start := env.Now()
			var at ConstructionSessionView
			env.RegisterDelayedCallback(func() { at = b12View(t, env) }, time.Minute)
			env.RegisterDelayedCallback(func() {
				env.SignalWorkflow(signalOperatorOverride, operatorOverrideSignal{Override: ActivityOverride{Kind: OverrideRetry, Notes: "retry it"}})
			}, 2*time.Minute)
			b12Run(env)
			if err := env.GetWorkflowError(); err != nil {
				t.Fatalf("workflow error: %v", err)
			}
			b12CheckEscalation(t, at, start, c.wait)
			if done := b12View(t, env); done.AwaitingGate != nil || done.Attempt != 2 {
				t.Fatalf("after the Retry gate=%v attempt=%d, want cleared and attempt 2", done.AwaitingGate, done.Attempt)
			}
		})
	}
}

// b12CheckEscalation asserts the view an escalation reports while it waits.
func b12CheckEscalation(t *testing.T, at ConstructionSessionView, start time.Time, wait time.Duration) {
	t.Helper()
	if at.Stage != StageAwaitingTakeover || b12Gate(at) != takeoverGateKey || at.AwaitingSince == nil || !at.AwaitingSince.Equal(start) {
		t.Fatalf("at the escalation: stage=%v gate=%q since=%v, want awaitingTakeover at takeover since %v", at.Stage, b12Gate(at), at.AwaitingSince, start)
	}
	switch {
	case wait > 0 && (at.AwaitingUntil == nil || !at.AwaitingUntil.Equal(start.Add(wait))):
		t.Fatalf("awaitingUntil = %v, want %v", at.AwaitingUntil, start.Add(wait))
	case wait == 0 && at.AwaitingUntil != nil:
		t.Fatalf("an indefinite wait has no deadline, got %v", at.AwaitingUntil)
	}
	if at.Attempt != 1 || at.RedraftExhausted {
		t.Fatalf("at the escalation attempt=%d exhausted=%v, want 1 and false", at.Attempt, at.RedraftExhausted)
	}
}

// The redraft budget reads spent once a further SendBack could not redraft (after four
// redrafts, not three), and the NEXT gate starts with a fresh budget (plan G5: the flag
// used to leak into every later gate).
func Test_SessionView_RedraftBudget_SpentAfterFourAndResetAtTheNextGate(t *testing.T) {
	var ts testsuite.WorkflowTestSuite
	env := ts.NewTestWorkflowEnvironment()
	ps := newFakeProjectStateWithPolicy(replayGatedOn(projectstate.MethodPhaseDetailedDesign, projectstate.MethodPhaseConstruction))
	registerConstruct(env, csNewWorkflows(gateDeps(ps)), ps, csNewFakePipeline())
	var afterThree, afterFour, nextGate ConstructionSessionView
	for i := 1; i <= 4; i++ {
		env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseSendBack), time.Duration(30*i)*time.Second)
	}
	env.RegisterDelayedCallback(func() { afterThree = b12View(t, env) }, 105*time.Second)
	env.RegisterDelayedCallback(func() { afterFour = b12View(t, env) }, 135*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "detailed_design", PhaseApprove), 150*time.Second)
	env.RegisterDelayedCallback(func() { nextGate = b12View(t, env) }, 165*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, "construction", PhaseApprove), 180*time.Second)
	env.RegisterDelayedCallback(b12Decide(env, mergeGateKey, PhaseApprove), 200*time.Second)
	b12Run(env)
	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow error: %v", err)
	}
	if afterThree.RedraftExhausted {
		t.Fatalf("after three redrafts one remains, but the view says the budget is spent")
	}
	if !afterFour.RedraftExhausted || b12Gate(afterFour) != "detailed_design" {
		t.Fatalf("after four redrafts gate=%q exhausted=%v, want detailed_design and spent", b12Gate(afterFour), afterFour.RedraftExhausted)
	}
	if b12Gate(nextGate) != "construction" || nextGate.RedraftExhausted {
		t.Fatalf("at the next gate gate=%q exhausted=%v, want construction with a fresh budget", b12Gate(nextGate), nextGate.RedraftExhausted)
	}
}

